MultiLanguageSpellData['de'][53] = {name = "Meucheln", additional_info = "{35 Energie} {Nahkampfreichweite}\nSofort\n[q]Meuchelt das Ziel und fügt ihm so 380% Waffenschaden plus 459 zu. Muss hinter dem Ziel sein. In der Waffenhand muss sich ein Dolch befinden. Gewährt 1 Combopunkt."}
MultiLanguageSpellData['de'][56] = {name = "Betäuben", additional_info = "Nahkampfreichweite\nSofort\n[q]Betäubt ein Ziel 3 Sek. lang."}
