MultiLanguageSpellData['de'][66] = {name = "Unsichtbarkeit", additional_info = "3% von Grundmana\nSofort 5 min Abklingzeit\n[q]Lässt den Zaubernden im Verlauf von 3 Sek. bis zur Unsichtbarkeit verblassen und verringert mit jeder Sekunde die Bedrohung. Während Ihr unsichtbar seid, könnt Ihr von Gegnern nicht als Ziel gewählt werden. Hält 20 Sek. lang an. [ Glyphe 'Unsichtbarkeit' : Während Ihr unsichtbar seid, ist Euer Bewegungstempo um 40% erhöht ]\n Der Effekt wird abgebrochen, wenn Ihr Aktionen ausführt."}
MultiLanguageSpellData['de'][71] = {name = "Verteidigungshaltung", additional_info = "{Sofort} {1.5 sek. Abklingzeit}\n[q]Eine defensive Kampfhaltung.\n\n Verringert den erlittenen Schaden um 25%.\n Erhöht außerdem die erzeugte Bedrohung deutlich.\n Erzeugt im Kampf alle 3 Sek. 1 Wut."}
MultiLanguageSpellData['de'][75] = {name = "Automatischer Schuss", additional_info = "40 Meter Reichweite\nSofort\nBenötigt Distanzwaffe\n[q]Schießt automatisch auf das Ziel, bis die Aktion abgebrochen wird."}
MultiLanguageSpellData['de'][77] = {name = "Schildkrötenpanzer", additional_info = nil}
MultiLanguageSpellData['de'][78] = {name = "Heldenhafter Stoß", additional_info = "{30 Wut} {Nahkampfreichweite}\n{Spontanzauber} {1.5 sek. Abklingzeit}\nBenötigt Nahkampfwaffe\n[q]Ein Angriff, der sofort 110% Waffenschaden plus 499 verursacht [154% plus ( 499 * 1.40) wenn eine Einhandwaffe angelegt ist] [ Glyphe 'Verwehrende Stöße' : Zusätzlich wird das Bewegungstempo des Ziels 8 Sek. lang um 50% verringert ].\n\n Setzt diese Fähigkeit ein, wenn Ihr überschüssige Wut zur Verfügung habt."}
MultiLanguageSpellData['de'][81] = {name = "Ausweichen", additional_info = "[q]Gewährt die Chance, Nahkampfattacken des Feindes auszuweichen."}
MultiLanguageSpellData['de'][87] = {name = "Automatische Immunität", additional_info = "Sofort\n[q]Macht Euch gegen alle Zaubermechanismen immun. Wird in automatischen Skripten verwendet, um Bots gegen negative Effekte immun zu machen, wobei diese weiterhin mit Objekten interagieren können."}
MultiLanguageSpellData['de'][89] = {name = "Verkrüppeln", additional_info = "30 Meter Reichweite\n{Sofort} {30 sek. Abklingzeit}\n[q]Verkrüppelt das Ziel, verringert dessen Bewegungstempo um 40 % und erhöht die Zeit zwischen Nahkampf- und Distanzangriffen um 26 %. Hält 20 Sek. lang an."}
MultiLanguageSpellData['de'][91] = {name = "Wilder Sturmangriff", additional_info = "Nächster Nahkampf"}
MultiLanguageSpellData['de'][96] = {name = "Zerstückeln", additional_info = "Nahkampfreichweite\nNächster Nahkampf\n[q]Erhöht den Schaden Eures nächsten Nahkampfangriffes um 100 und lässt das Ziel bluten."}
MultiLanguageSpellData['de'][99] = {name = "Desorientierendes Gebrüll", additional_info = "{Sofort} {30 sek. Abklingzeit}\n[q]Ruft den Geist Ursols an, dessen Brüllen alle Gegner innerhalb von 10 Metern 3 Sek. lang desorientiert. Jeglicher zugefügter Schaden wird den Effekt abbrechen. In allen Gestalten einsetzbar."}
MultiLanguageSpellData['de'][100] = {name = "Sturmangriff", additional_info = "8 - 25 Meter Reichweite\n{Sofort} {20 sek. Abklingzeit}\n[q]Furor ( Hotfix - Passivfähigkeit )\n Stürmt auf einen Gegner zu und betäubt ihn . Hält 1.50 Sek. lang an . Erzeugt 20 Wut.\n\n Waffen, Schutz\n Stürmt auf einen Gegner zu und [ Kriegstreiber : macht ihn bewegungsunfähig / betäubt ihn]. [ Glyphe 'Blitz' : Wirkt sich außerdem auf 2 weitere Ziele in der Nähe aus ] Hält [ Kriegstreiber : 4 Sek. lang an und verringert das Bewegungstempo des Ziels 15 Sek. lang um 50% / 1.50 Sek. lang an]. Erzeugt 20 Wut."}
MultiLanguageSpellData['de'][101] = {name = "Straucheln", additional_info = "{15 Energie} {Nahkampfreichweite}\n{Sofort} {5 sek. Abklingzeit}\n[q]Bringt den humanoiden Feind zu Fall, wobei 10 Schaden verursacht werden und der Gegner 3 Sek. lang am Boden liegt. Gewährt 1 Combopunkt."}
MultiLanguageSpellData['de'][107] = {name = "Blocken", additional_info = "Benötigt Schild\n[q]Gewährt die Chance, Nahkampfattacken und Distanzangriffe des Feindes zu blocken."}
