MultiLanguageSpellData['de'][113] = {name = "Eisketten", additional_info = "{20 Mana} {30 Meter Reichweite}\nWirken in 1.5 sek.\n[q]Schlingt eisige Ketten um das Ziel, welche es 6 Sek. lang an Ort und Stelle festhalten."}
MultiLanguageSpellData['de'][116] = {name = "Frostblitz", additional_info = "{4% von Grundmana} {40 Meter Reichweite}\nWirken in 2 sek.\n[q]Schleudert einen Frostblitz auf den Gegner, der 1 Frostschaden verursacht und sein Bewegungstempo 15 Sek. lang um 50% verringert."}
MultiLanguageSpellData['de'][118] = {name = "Verwandlung", additional_info = "{2% von Grundmana} {30 Meter Reichweite}\nWirken in 1.7 sek.\n[q]Verwandelt den Gegner in [ Glyphe 'Pinguin' : einen harmlosen Pinguin ] [ Glyphe 'Affe' : einen harmlosen Affen ] [ Glyphe 'Stachelschwein' : ein harmloses Stachelschwein ] [ Glyphe 'Bärenjunges' : ein harmloses Eisbärenjunges / ein harmloses Schaf ] und zwingt ihn, 50 Sek. lang so herumzuwandern.\n\n Während der Gegner in [ Glyphe 'Pinguin' : einen Pinguin ] [ Glyphe 'Affe' : einen Affen ] [ Glyphe 'Stachelschwein' : ein Stachelschwein ] [ Glyphe 'Bärenjunges' : ein Eisbärenjunges / ein Schaf ] verwandelt ist, kann er weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden wandelt ihn in seine normale Gestalt zurück.\n\n Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren."}
MultiLanguageSpellData['de'][120] = {name = "Kältekegel", additional_info = "4% von Grundmana\n{Sofort} {10 sek. Abklingzeit}\n[q]Fügt Zielen in einem kegelförmigen Bereich vor dem Zaubernden 1 Frostschaden zu und verlangsamt sie 6 Sek. lang um 60%."}
MultiLanguageSpellData['de'][122] = {name = "Frostnova", additional_info = "2% von Grundmana\n{Sofort} {25 sek. Abklingzeit}\n[q]Fügt nahen Gegnern innerhalb von 12 Metern im Umkreis um den Zaubernden 552 Frostschaden zu und friert sie bis zu 8 Sek. lang fest. Erlittener Schaden kann den Effekt unterbrechen."}
MultiLanguageSpellData['de'][124] = {name = "Heilige Handgranate des Widerstands", additional_info = "30 Meter Reichweite\n{Sofort} {5 sek. Abklingzeit}\n[q]Segnet alle Ziele mit einer heiligen Machtinfusion oder verflucht sie mit dem Bann aller Schlachtzügler."}
MultiLanguageSpellData['de'][126] = {name = "Auge von Kilrogg", additional_info = "4% von Grundmana Unbegrenzte Reichweite\nWirken in 2 sek.\n[q]Beschwört das Auge von Kilrogg und bindet Eure Sicht daran. Das Auge [ Glyphe 'Auge von Kilrogg' : fliegt sehr schnell / ist verstohlen und bewegt sich schnell], ist jedoch sehr fragil. [ Glyphe 'Auge von Kilrogg' : Wenn Ihr 'Dämonischer Zirkel: Beschwören' wirkt, während Ihr ein Auge von Kilrogg kontrolliert, wird der Beschwörungszirkel an der Position des Auges erscheinen ]"}
MultiLanguageSpellData['de'][130] = {name = "Langsamer Fall", additional_info = "{1% von Grundmana} {40 Meter Reichweite}\nSofort\n[q]Verringert 30 Sek. lang das Falltempo eines verbündeten Gruppen- oder Schlachtzugsmitglieds."}
