MultiLanguageSpellData['de'][134] = {name = "Feuerschild", additional_info = "30 Meter Reichweite\n{Wirken in} {1 sek. 15 sek. Abklingzeit}\n[q]Umgibt einen Verbündeten mit einem Flammenschild, der alle 3 Sek. in der Nähe befindlichen Feinden 9 Feuerschaden zufügt. Hält 1 Min. lang an."}
MultiLanguageSpellData['de'][136] = {name = "Tier heilen", additional_info = "45 Meter Reichweite\nSofort\n[q]Heilt Euren Begleiter im Verlauf von 10 Sek. um [ Glyphe 'Besserung' : 50 / 25]% seiner gesamten Gesundheit. [ Glyphe 'Tier heilen' : Pro Tick besteht eine Chance von 100%, 1 Fluch-, Krankheits-, Magie- oder Gifteffekt von Eurem Begleiter zu entfernen ]"}
