MultiLanguageSpellData['de'][348] = {name = "Feuerbrand", additional_info = "{3% von Grundmana} {40 Meter Reichweite}\nWirken in 1.5 sek.\n[q]Fügt dem Ziel 1 Feuerschaden sowie im Verlauf von 15 Sek. zusätzlich 2510 Feuerschaden zu. [ Instabile Funken : Kritische Treffer erzeugen instabile Funken ]\n Ersetzt 'Verderbnis'."}
MultiLanguageSpellData['de'][355] = {name = "Spott", additional_info = "30 Meter Reichweite\n{Sofort} {8 sek. Abklingzeit}\n[q]Verspottet das Ziel, damit es Euch angreift, und erhöht die von Euch gegen das Ziel erzeugte Bedrohung für 3 Sek. um 200%."}
MultiLanguageSpellData['de'][370] = {name = "Reinigen", additional_info = "{16.4% von Grundmana} {30 Meter Reichweite}\nSofort\n[q]Reinigt das gegnerische Ziel und entzieht 1 nützlichen magischen Effekt.\n [Ist 'Reinigen' erfolgreich, wird Euch eine Aufladung von 'Waffe des Mahlstroms' gewährt.]"}
MultiLanguageSpellData['de'][379] = {name = "Erdschild", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Schützt das Ziel mit einem Erdschild, der eine Chance gewährt, Zauberunterbrechungen durch Schaden zu vermeiden. Angriffe heilen das geschützte Ziel, dieser Effekt kann jedoch nur einmal innerhalb einiger Sekunden ausgelöst werden. Begrenzte Aufladungen. Dieser Schild kann immer nur auf einem Ziel gleichzeitig aktiv sein, und auf jedem Ziel kann nur ein Elementarschild aktiv sein."}
