MultiLanguageSpellData['de'][527] = {name = "Läutern", additional_info = "{2.6% von Grundmana} {40 Meter Reichweite}\n{Sofort} {8 sek. Abklingzeit}\n[q]Bannt auf das Ziel wirkende schädliche Effekte. Es werden magische Schwächungszauber und Krankheiten entfernt."}
