MultiLanguageSpellData['de'][585] = {name = "Heilige Pein", additional_info = "{2.7% von Grundmana} {30 Meter Reichweite}\nWirken in 1.5 sek.\n[q]Zerschmettert einen Feind und fügt ihm 2361 Heiligschaden zu. [ Glyphe 'Heilige Pein' : Wenn das Ziel von Eurem Zauber 'Heiliges Feuer' betroffen ist, wird der Schaden von 'Heilige Pein' um 20% erhöht ] [ Wenn das Ziel von Eurem Zauber 'Machtwort: Trost' betroffen ist, wird der Schaden von 'Heilige Pein' um 20% erhöht ]"}
MultiLanguageSpellData['de'][586] = {name = "Verblassen", additional_info = "3.5% von Grundmana\n{Sofort} {30 sek. Abklingzeit}\n[q]Lässt Euch verblassen und entfernt so zeitweilig Eure gesamte Bedrohung. [ Glyphe 'Schleier' : Zudem wird Euer erlittener Schaden um 10% verringert ] Hält 10 Sek. lang an. [ Phantom : Wenn Ihr verblasst, befreit Ihr Euch von allen bewegungseinschränkenden Effekten und Euer Bewegungstempo kann 5 Sek. lang nicht eingeschränkt werden. ]"}
MultiLanguageSpellData['de'][588] = {name = "Inneres Feuer", additional_info = "Sofort\n[q]Der Zaubernde wird von einem Schub heiliger Energie erfüllt, der seinen durch Gegenstände erhaltenen Rüstungswert um 60 % und seine Zaubermacht um 10% erhöht. [ Innerer Wille : Es kann nur entweder 'Innerer Wille' oder 'Inneres Feuer' aktiv sein ]"}
MultiLanguageSpellData['de'][589] = {name = "Schattenwort: Schmerz", additional_info = "{4.4% von Grundmana} {40 Meter Reichweite}\nSofort\n[q]Ein Wort der Dunkelheit, das sofort 780 Schattenschaden sowie im Verlauf von 18 Sek. zusätzlich ( 4678 - 780 ) Schattenschaden verursacht."}
MultiLanguageSpellData['de'][596] = {name = "Gebet der Heilung", additional_info = "{4.5% von Grundmana} {40 Meter Reichweite}\nWirken in 2.5 sek.\n[q]Ein machtvolles Gebet heilt alle Gruppenmitglieder des befreundeten Ziels in einem Umkreis von 30 Metern um 8689 ."}
MultiLanguageSpellData['de'][603] = {name = "Verdammnis", additional_info = "60 Dämonischer Furor 40 Meter Reichweite\nSpontanzauber\n[q]Verflucht das Ziel mit drohender Verdammnis, die im Verlauf von 1 Min. 4006 Schattenschaden verursacht.\n\n Wenn 'Verdammnis' einen kritischen Treffer erzielt, wird ein Wildwichtel beschworen, der das Ziel angreift."}
MultiLanguageSpellData['de'][605] = {name = "Gedankenkontrolle", additional_info = "{2% von Grundmana} {30 Meter Reichweite}\nWirken in 1.8 sek."}
MultiLanguageSpellData['de'][606] = {name = "Gedankenverfall", additional_info = "{240 Mana} {30 Meter Reichweite}\nWirken in 2 sek.\n[q]Entzieht dem Ziel 30 Sek. lang insgesamt 2160 Mana."}
MultiLanguageSpellData['de'][611] = {name = "Siegel der Aufopferung", additional_info = "Wirken in 3 sek."}
MultiLanguageSpellData['de'][633] = {name = "Handauflegung", additional_info = "40 Meter Reichweite\nSofort 10 min Abklingzeit\n[q]Heilt ein befreundetes Ziel um einen Betrag, der Eurer maximalen Gesundheit entspricht [ Glyphe 'Göttlichkeit' : zudem regeneriert Ihr 10% Eures maximalen Manas ].\n\n Kann nicht auf Ziele gewirkt werden, die von 'Vorahnung' betroffen sind. Ruft den Effekt 'Vorahnung' hervor, der 1 Min. lang anhält."}
