MultiLanguageSpellData['de'][676] = {name = "Entwaffnen", additional_info = "Nahkampfreichweite\nSofort 1 min Abklingzeit\n[q]Entwaffnet den Gegner 8 Sek. lang, sodass dieser seine Waffe und seinen Schild zeitweilig verliert. Entwaffnete Kreaturen verursachen deutlich weniger Schaden."}
MultiLanguageSpellData['de'][686] = {name = "Schattenblitz", additional_info = "{40 Dämonischer Furor / 5.5% von Grundmana} {40 Meter Reichweite}\nWirken in 1.7 sek.\n[q]Schleudert einen Schattenblitz auf den Gegner, der 1 Schattenschaden verursacht."}
MultiLanguageSpellData['de'][688] = {name = "Wichtel beschwören", additional_info = "20% von Grunddämonischer furor / 20% von Grundmana\nWirken in 5 sek.\n[q]Beschwört einen Wichtel, der unter dem Befehl des Hexenmeisters steht.\n\n Wichtel wirken den Distanzzauber 'Feuerblitz' [ Wichtel: Meister kauterisieren : können ihren Meister im Verlauf der Zeit heilen ] [ Wichtel: Magie versengen : schädliche Magieeffekte läutern ] . [ Seelenbrand : Seelenbrand:\nSpontanzauber. ]"}
MultiLanguageSpellData['de'][689] = {name = "Blutsauger", additional_info = "{1% von Grundmana} {, plus 1% pro Sekunde 40 Meter Reichweite}\nKanalisiert (Wirken in 6 sek.)\n[q]Entzieht dem Ziel Leben, wodurch es alle 1 Sek. ( 357 + 0.334 * Zaubermacht) Schattenschaden erleidet und der Zaubernde 2% seiner gesamten Gesundheit regeneriert. Hält 6 Sek. lang an. [ Seelenbrand : Seelenbrand:\nErhöht den Heilungseffekt um 50%. ]"}
MultiLanguageSpellData['de'][691] = {name = "Teufelsjäger beschwören", additional_info = "20% von Grunddämonischer furor / 25% von Grundmana\nWirken in 5 sek.\n[q]Beschwört einen Teufelsjäger, der unter dem Befehl des Hexenmeisters steht.\n\n Teufelsjäger werden von Magie angezogen [ Teufelsjäger: Zaubersperre : unterbrechen das Wirken von Zaubern ] und können sich selbst heilen, indem sie auf das gegnerische Ziel wirkende magische Stärkungszauber aufzehren. [ Seelenbrand : Seelenbrand:\nSpontanzauber. ]"}
MultiLanguageSpellData['de'][697] = {name = "Leerwandler beschwören", additional_info = "20% von Grunddämonischer furor / 25% von Grundmana\nWirken in 5 sek.\n[q]Beschwört einen Leerwandler, der unter dem Befehl des Hexenmeisters steht.\n\n Leerwandler können schwerem Schaden widerstehen [ Leerwandler: Entwaffnen : Nahkampfangreifer entwaffnen ] [ Leerwandler: Schattenschild : angreifenden Gegnern Schattenschaden zufügen ] [ Leerwandler: Schattenbollwerk : ihre Gesundheit erhöhen, wenn ihnen der Tod bevorsteht ] [ Leerwandler: Leiden : und Gegner verspotten, die ihren Meister angreifen / . ] [ Seelenbrand : Seelenbrand:\nSpontanzauber. ]"}
MultiLanguageSpellData['de'][698] = {name = "Ritual der Beschwörung", additional_info = "{4% von Grundmana} {30 Meter Reichweite}\nKanalisiert (Wirken in 2 min) 2 min Abklingzeit\n[q]Führt ein Ritual zur Erschaffung eines Beschwörungsportals durch, das von Verbündeten benutzt werden kann, um ein ausgewähltes Gruppen- oder Schlachtzugsmitglied zu beschwören.\n\nRituale\nZur Vervollständigung des Zaubers werden der Zaubernde und zwei weitere Verbündete benötigt."}
MultiLanguageSpellData['de'][700] = {name = "Schlaf", additional_info = "{60 Mana} {30 Meter Reichweite}\nWirken in 1.5 sek."}
MultiLanguageSpellData['de'][703] = {name = "Erdrosseln", additional_info = "{45 Energie} {Nahkampfreichweite}\nSofort\nBenötigt Verstohlenheit\n[q]Erdrosselt den Gegner, bringt ihn 3 Sek. lang zum Schweigen und verursacht im Verlauf von 18 Sek. [( 147 + Angriffskraft * 0.078) * 6] Schaden, erhöht durch Eure Angriffskraft. Muss im Verstohlenheitsmodus sein. Gewährt 1 Combopunkt [ Mantel und Degen : und lässt Euch hinter dem Ziel erscheinen ]."}
MultiLanguageSpellData['de'][710] = {name = "Verbannen", additional_info = "{30 Dämonischer Furor / 3% von Grundmana} {30 Meter Reichweite}\nWirken in 1.5 sek.\n[q]Verbannt bis zu 30 Sek. lang einen gegnerischen Dämon, Elementar oder eine gegnerische Entartung.\n\nVerbannt\nVerhindert alle Aktionen des Ziels, macht es jedoch unverwundbar. Es kann immer nur jeweils eine Verbannung aktiv sein.\n\n Wenn 'Verbannung' erneut gewirkt wird, wird der bestehende Effekt abgebrochen."}
MultiLanguageSpellData['de'][712] = {name = "Sukkubus beschwören", additional_info = "20% von Grunddämonischer furor / 25% von Grundmana\nWirken in 5 sek.\n[q]Beschwört einen Sukkubus, der unter dem Befehl des Hexenmeisters steht.\n\n Sukkuben sind gefährliche Magier, die den Nahkampf bevorzugen. Sie können [ Sukkubus: Geringe Unsichtbarkeit : unsichtbar werden ] [ Sukkubus: Peitschen : Ziele zurückstoßen ] [ Sukkubus: Geringe Unsichtbarkeit : und ] humanoide Gegner betören, die dadurch nicht angreifen können. [ Seelenbrand : Seelenbrand:\nSpontanzauber. ]"}
MultiLanguageSpellData['de'][713] = {name = "Inkubus beschwören", additional_info = "25% von Grundmana / 20% von Grunddämonischer furor\nWirken in 5 sek.\n[q]Beschwört einen Inkubus, der unter dem Befehl des Hexenmeisters steht.\n\n Inkuben sind gefährliche Zauberwirker, die aus kurzer Distanz angreifen. Sie können sich [ Sukkubus: Geringe Unsichtbarkeit : unsichtbar machen ] [ Sukkubus: Peitschen : Gegner wegstoßen ] [ Sukkubus: Geringe Unsichtbarkeit : und ] humanoide Kreaturen verführen, was sie am Angreifen hindert. [ Seelenbrand : Seelenbrand:\nSpontanzauber. ]"}
MultiLanguageSpellData['de'][720] = {name = "Umschlingen", additional_info = "Sofort\n[q]Die Brutstätte Fankriss' des Unnachgiebigen zieht das Ziel nahen Silithidjungtieren entgegen und macht es 8 Sek. lang bewegungsunfähig."}
MultiLanguageSpellData['de'][724] = {name = "Lichtbrunnen", additional_info = "{5.4% von Grundmana} {40 Meter Reichweite}\nWirken in 0.5 sek. 3 min Abklingzeit\n[q]Erschafft einen heiligen Lichtbrunnen. Verbündete Spielercharaktere können den Lichtbrunnen anklicken, um 6 Sek. lang alle 2 Sek. um [(( 5735 + (Zaubermacht * .553))) * 1.5] Gesundheit geheilt zu werden. Erlittene Angriffe, die 30% Eurer Gesamtgesundheit entsprechen, heben diesen Effekt auf. Der Lichtbrunnen bleibt 3 Min. oder 15 Aufladungen lang bestehen."}
MultiLanguageSpellData['de'][731] = {name = "Umschlingen", additional_info = "Sofort\n[q]Die Brutstätte Fankriss' des Unnachgiebigen zieht das Ziel nahen Silithidjungtieren entgegen und macht es 8 Sek. lang bewegungsunfähig."}
MultiLanguageSpellData['de'][740] = {name = "Gelassenheit", additional_info = "27.1% von GrundmanaKanalisiert (Wirken in 8 sek.) 8 min Abklingzeit\n[q]Heilt die 5 (12 in 25 - Spieler - Instanzen) Gruppen- oder Schlachtzugsmitglieder innerhalb von 40 Metern, deren Gesundheit am niedrigsten ist, 8 Sek. lang alle 2 Sek. um 9037 Gesundheit.\n\n Zusätzlich heilt 'Gelassenheit' 8 Sek. lang alle 2 Sek. um 1 Gesundheit. Bis zu 3-mal stapelbar. Der Druide muss seine Kräfte kanalisieren, um den Zauber aufrechtzuerhalten."}
MultiLanguageSpellData['de'][742] = {name = "Pulverisieren", additional_info = "10 min Abklingzeit\n(Procchance: 35%)"}
MultiLanguageSpellData['de'][744] = {name = "Gift", additional_info = "Nahkampfreichweite\nSofort\n[q]Fügt einem Gegner 15 Sek. lang alle 3 Sek. Naturschaden zu."}
MultiLanguageSpellData['de'][745] = {name = "Gespinst", additional_info = "30 Meter Reichweite\nSofort\n[q]Zaubert ein Netz über einen Feind und macht ihn so 5 Sek. lang bewegungsunfähig."}
MultiLanguageSpellData['de'][746] = {name = "Erste Hilfe", additional_info = "15 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\n[q]Heilt im Verlauf von 6 Sek. 66 Schaden."}
MultiLanguageSpellData['de'][747] = {name = "Abbilder beschwören", additional_info = "Sofort\n[q]Beschwört 2 Kopien des Zaubernden."}
MultiLanguageSpellData['de'][750] = {name = "Plattenpanzer", additional_info = "[q]Gestattet Euch, Gegenstände der Kategorie 'Plattenrüstung' anzulegen."}
MultiLanguageSpellData['de'][755] = {name = "Lebenslinie", additional_info = "45 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\n[q]Opfert 2% Eurer gesamten Gesundheit, um Euren beschworenen Dämon alle 1 Sek. um 6% seiner gesamten Gesundheit zu heilen. Hält 6 Sek. lang an.\n [\nMachterfüllte Kanalisierung\nWenn dieser Zauber erneut gewirkt wird, bevor seine Effektdauer endet, wird die Effektdauer um 0.05 Sek. erhöht.\n Bis zu 0-mal stapelbar. ] [ Seelenbrand: Lebenslinie : Seelenbrand:\nRegeneriert 140% mehr Gesundheit und verringert den erlittenen Schaden 10 Sek. lang um 30%. ]"}
MultiLanguageSpellData['de'][759] = {name = "Manaedelstein herbeizaubern", additional_info = "18% von Grundmana\nWirken in 3 sek.\n[q]Zaubert einen Manaedelstein herbei, der [ Glyphe 'Ungebundenes Mana' : im Verlauf von bis Abbruch 0 Mana wiederherstellt / sofort 45000 Mana wiederherstellt] und bis zu 3 Aufladungen hat.\n\nHerbeigezauberte Gegenstände\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Min. ausloggt."}
MultiLanguageSpellData['de'][768] = {name = "Katzengestalt", additional_info = "3.7% von Grundmana\nSofort\n[q]Verwandelt Eure Gestalt in die einer Katze und bewirkt, dass Beweglichkeit die Angriffskraft erhöht, erhöht den von Euren automatischen Angriffen verursachten Schaden um 100% und Euer Bewegungstempo um 25% (kumulativ mit den meisten anderen Beschleunigungseffekten). [ Glyphe 'Katzengestalt' : Erhöht außerdem sämtliche von Euch erhaltene Heilung um 20% ]\n Beschützt Euch außerdem vor Verwandlungseffekten und erlaubt den Einsatz von verschiedenen Katzenfähigkeiten.\n\n Energieregeneration dauert an, während Ihr Euch nicht in Katzengestalt befindet.\n\n Der Akt des Gestaltwandelns befreit Euch von bewegungseinschränkenden Effekten."}
MultiLanguageSpellData['de'][770] = {name = "Feenfeuer", additional_info = "{7.5% von Grundmana} {35 Meter Reichweite}\nSofort\n[q]Feen tummeln sich um das Ziel, hindern es daran, Verstohlenheit einzusetzen oder unsichtbar zu werden, und belegen es mit 3 Stapeln des Effekts 'Rüstungsschwächung'.\n\n Verursacht 10 Schaden, [ Glyphe 'Feenstille' : bringt das Ziel 3 Sek. lang zum Schweigen ] und gewährt eine Chance von 25%, die Abklingzeit von 'Zerfleischen' abzuschließen, wenn es in Bärengestalt gewirkt wird.\n\n Rüstungsschwächung\n Schwächt die Rüstung des Ziels 30 Sek. lang um 4%. Bis zu 3-mal stapelbar."}
MultiLanguageSpellData['de'][774] = {name = "Verjüngung", additional_info = "{14.5% von Grundmana} {40 Meter Reichweite}\nSofort\n[q]Heilt das Ziel um 1 und zusätzlich 12 Sek. lang alle 3 Sek. um 1 ."}
MultiLanguageSpellData['de'][779] = {name = "Prankenhieb", additional_info = "{15 Wut} {8 Meter Reichweite}\n{Spontanzauber} {3 sek. Abklingzeit}\nBenötigt Bärengestalt\n[q]Schlägt Gegner in der Nähe und verursacht so 246 Schaden.\n\n Fügt blutenden Zielen 20% zusätzlichen Schaden zu."}
MultiLanguageSpellData['de'][781] = {name = "Rückzug", additional_info = "Unbegrenzte Reichweite\n{Sofort} {20 sek. Abklingzeit}\n[q]Ihr versucht, rückwärts zu springen. [ Impromptu : Außerdem werdet Ihr von bewegungseinschränkenden Effekten befreit und Euer Bewegungstempo wird 8 Sek. lang um 60% erhöht ] [ Um ein Haar : Es wird gleichzeitig eine Netzfalle aktiviert, die alle Ziele im Umkreis von 8 Metern mit klebrigen Netzen bedeckt. Diese Netze machen alle Ziele 8 Sek. lang bewegungsunfähig ] [ Glyphe 'Befreiung' : Zusätzlich werdet Ihr um 5% Eurer gesamten Gesundheit geheilt ]"}
MultiLanguageSpellData['de'][783] = {name = "Reisegestalt", additional_info = "5.6% von Grundmana\nSofort\n[q]Verwandelt Euch in eine Reisegestalt und erhöht Euer Bewegungstempo um 40%. Beschützt Euch außerdem vor Verwandlungseffekten. Kann nur im Freien verwendet werden.\n\n Der Akt des Gestaltwandelns befreit Euch von bewegungseinschränkenden Effekten."}
MultiLanguageSpellData['de'][785] = {name = "Wahre Erfüllung", additional_info = "{260 Mana} {45 Meter Reichweite}\nWirken in 0.5 sek.\n[q]Von den Kräften des Propheten Skeram bekehrt, wird das Ziel mit heiliger Macht erfüllt. Die Zauber des Ziels werden sofort gewirkt, der verursachte Schaden ist um 300%, alle Widerstände sind um 50 und das Bewegungstempo ist um 40% erhöht. Hält 20 Sek. lang an."}
