MultiLanguageSpellData['de'][845] = {name = "Spalten", additional_info = "{30 Wut} {Nahkampfreichweite}\n{Spontanzauber} {1.5 sek. Abklingzeit}\nBenötigt Nahkampfwaffe\n[q]Ein weitreichender Angriff, der das Ziel sowie ein weiteres in der Nähe trifft. Verursacht 82% Waffenschaden (115%, wenn eine Einhandwaffe ausgerüstet ist) [ Glyphe 'Verwehrende Stöße' : und verringert das Bewegungstempo des Ziels 8 Sek. lang um 50% ].\n\n Setzt diese Fähigkeit ein, wenn Ihr überschüssige Wut zur Verfügung habt."}
MultiLanguageSpellData['de'][851] = {name = "Verwandlung: Schaf", additional_info = "{200 Mana} {20 Meter Reichweite}\nSofort\n[q]Verwandelt den Feind bis zu 10 Sek. lang in ein hilfloses Schaf, das weder Zauber wirken noch angreifen kann und sich um 60% langsamer bewegt."}
