MultiLanguageSpellData['de'][974] = {name = "Erdschild", additional_info = "{19% von Grundmana} {40 Meter Reichweite}\nSofort\n[q]Schützt das Ziel mit einem Erdschild, der die Effektivität schamanischer Heilzauber bei diesem Ziel um 20% erhöht und das geschützte Ziel bei Angriffen um ( 2043 + Zaubermacht * 0.13) heilt. 9 Aufladungen. Hält 10 Min. lang an. Dieser Effekt tritt nur einmal alle paar Sekunden auf.\n\n 'Erdschild' kann immer nur auf einem Ziel gleichzeitig aktiv sein, auf jedem Ziel kann nur ein Erdschild aktiv sein und es kann immer nur eins der Elementarschilde auf dem Schamanen aktiv sein.\n(3.5s Abklingzeit)"}
MultiLanguageSpellData['de'][980] = {name = "Agonie", additional_info = "{1% von Grundmana} {40 Meter Reichweite}\nSofort\n[q]Fügt dem Ziel immer stärkere Schmerzen zu, die im Verlauf von 24 Sek. bis zu ( 327 * 10) Schattenschaden verursachen.\n\n Zunächst wird nur geringer Schaden verursacht, der aber mit jedem Tick zunimmt."}
MultiLanguageSpellData['de'][982] = {name = "Tier wiederbeleben", additional_info = "35 Fokus\nWirken in 4 sek.\n[q]Bringt Euer totes Tier mit 100% seiner Grundgesundheit wieder ins Leben zurück."}
MultiLanguageSpellData['de'][1022] = {name = "Hand des Schutzes", additional_info = "{7% von Grundmana} {40 Meter Reichweite}\nSofort 5 min Abklingzeit\n[q]Legt eine Hand auf ein Gruppen- oder Schlachtzugsmitglied und schützt es 10 Sek. lang vor allen körperlichen Angriffen, allerdings kann es dabei weder angreifen noch körperliche Fähigkeiten einsetzen. Spielercharaktere können pro Paladin immer nur von einer Hand berührt werden.\n\n Kann nicht auf Ziele gewirkt werden, die von 'Vorahnung' betroffen sind. Ruft den Effekt 'Vorahnung' hervor, der 1 Min. lang anhält."}
MultiLanguageSpellData['de'][1038] = {name = "Hand der Erlösung", additional_info = "{6% von Grundmana} {40 Meter Reichweite}\nSofort 2 min Abklingzeit\n[q]Legt eine Hand auf das Gruppen- oder Schlachtzugsmitglied, die seine gesamte Bedrohung 10 Sek. lang entfernt. Spielercharaktere können pro Paladin immer nur von einer Hand berührt werden."}
MultiLanguageSpellData['de'][1044] = {name = "Hand der Freiheit", additional_info = "{7% von Grundmana} {40 Meter Reichweite}\n{Sofort} {25 sek. Abklingzeit}\n[q]Legt eine Hand auf ein verbündetes Ziel und gewährt ihm so 6 Sek. lang Immunität gegen jegliche bewegungseinschränkenden Effekte. Spielercharaktere können pro Paladin immer nur von einer Hand berührt werden."}
MultiLanguageSpellData['de'][1050] = {name = "Opferung", additional_info = "Wirken in 1 sek."}
MultiLanguageSpellData['de'][1064] = {name = "Kettenheilung", additional_info = "{22.5% von Grundmana} {40 Meter Reichweite}\nWirken in 2.5 sek.\n[q]Heilt das befreundete Ziel um 7590 und springt dann weiter, um die am schwersten verletzten Ziele in der Nähe zu heilen. Wenn der Zauber auf ein Gruppenmitglied gewirkt wird, springt die Heilung nur auf andere Gruppenmitglieder über. [ Wiederherstellung : Außerhalb von Arenen und Schlachtfeldern verringert sich die Heilwirkung mit jedem Sprung um 20% ] Heilt insgesamt 4 Ziele."}
MultiLanguageSpellData['de'][1066] = {name = "Wassergestalt", additional_info = "5.6% von Grundmana\nSofort\n[q]Verwandelt Euch in eine Wassergestalt. Das Schwimmtempo wird um 50% erhöht und Ihr könnt unter Wasser atmen. Beschützt Euch außerdem vor Verwandlungseffekten.\n\n Der Akt des Gestaltwandelns befreit Euch von bewegungseinschränkenden Effekten."}
MultiLanguageSpellData['de'][1079] = {name = "Zerfetzen", additional_info = "{30 Energie} {Nahkampfreichweite}\nSofort\nBenötigt Katzengestalt\n[q]Finishing-Move, der im Lauf der Zeit Blutungsschaden verursacht. Der Schaden erhöht sich pro Combopunkt:\n\n 1 Punkt: [floor(((((4 + (Angriffskraft * 0.0484)))) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] Schaden im Verlauf von 16 Sek.\n 2 Punkte: [floor(((((4 + (Angriffskraft * 0.0484))) * 2) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] Schaden im Verlauf von 16 Sek.\n 3 Punkte: [floor(((((4 + (Angriffskraft * 0.0484))) * 3) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] Schaden im Verlauf von 16 Sek.\n 4 Punkte: [floor(((((4 + (Angriffskraft * 0.0484))) * 4) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] Schaden im Verlauf von 16 Sek.\n 5 Punkte: [floor(((((4 + (Angriffskraft * 0.0484))) * 5) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] Schaden im Verlauf von 16 Sek.\n\n Jedes Mal, wenn Ihr in Katzengestalt Eure Fähigkeiten 'Schreddern', 'Verheeren' oder 'Zerfleischen' einsetzt, wird die Dauer eines bestehenden Effekts von 'Zerfetzen' auf dem Ziel um 2 Sek. erhöht, bis zu einem Maximum von 6 Sek."}
MultiLanguageSpellData['de'][1090] = {name = "Schlaf", additional_info = "{90 Mana} {30 Meter Reichweite}\nWirken in 1.5 sek."}
MultiLanguageSpellData['de'][1098] = {name = "Dämon unterwerfen", additional_info = "{5% von Grundmana} {30 Meter Reichweite}\nWirken in 3 sek.\n[q]Unterwirft den Zieldämon und zwingt ihn, Euch zu dienen. Hält bis zu 5 Min. lang an.\n\nUnterworfen\nWährend der Dämon unterworfen ist, wird die Zeit zwischen seinen Angriffen um 30% erhöht und sein Zaubertempo um 20% verlangsamt."}
MultiLanguageSpellData['de'][1120] = {name = "Seelendieb", additional_info = "{1.5% von Grundmana} {, plus 1.5% pro Sekunde 40 Meter Reichweite}\nKanalisiert (Wirken in 12 sek.)\n[q]Entzieht dem Ziel die Seele, wodurch es alle 2 Sek. ( 275 + Zaubermacht * 0.257) Schattenschaden erleidet und nach jedem zweiten Schaden verursachenden Tick ein Seelensplitter aufgefüllt wird. Wenn das Ziel stirbt und Erfahrung oder Ehre gewährt, werden 4 Seelensplitter aufgefüllt. Hält 12 Sek. lang an.\n\n Wenn das Ziel über 20% Gesundheit oder weniger verfügt, verursacht 'Seelenentzug' 100% zusätzlichen Schaden und lässt alle Eure anderen regelmäßigen Gebrechenseffekte sofort 60% ihres normalen regelmäßigen Schadens verursachen."}
MultiLanguageSpellData['de'][1121] = {name = "Umschlingen", additional_info = "100 Meter Reichweite\nSofort\n[q]Die Brutstätte Fankriss' des Unnachgiebigen zieht das Ziel nahen Silithidjungtieren entgegen und macht es 8 Sek. lang bewegungsunfähig."}
MultiLanguageSpellData['de'][1122] = {name = "Höllenbestie beschwören", additional_info = "{25% von Grundmana} {30 Meter Reichweite}\nSofort 10 min Abklingzeit\n[q]Beschwört einen Meteor aus dem Wirbelnden Nether, der allen Gegnern im Zielgebiet 1069 Feuerschaden zufügt und sie 2 Sek. lang betäubt. Aus dem Krater erhebt sich eine Höllenbestie, die 1 Min. lang unter dem Befehl des Zaubernden steht.\n\n Die Höllenbestie verursacht schweren Flächenschaden und wird Ziele in der Nähe des Einschlagsortes angreifen."}
MultiLanguageSpellData['de'][1126] = {name = "Mal der Wildnis", additional_info = "{5% von Grundmana} {30 Meter Reichweite}\nSofort\n[q]Erhöht die Stärke, Beweglichkeit und Intelligenz des verbündeten Ziels für 1 Stunde um 5%.\n\n Wenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, werden alle Mitglieder den Effekt erhalten."}
