MultiLanguageSpellData['de'][1449] = {name = "Arkane Explosion", additional_info = "3% von Grundmana\nSofort\n[q]Verursacht eine Explosion arkaner Magie um den Zaubernden herum, die allen Zielen im Umkreis von 10 Metern 503 Arkanschaden zufügt. [ Arkane Aufladung : Frischt bestehende Arkane Aufladungen auf und hat eine Chance von 30%, eine Arkane Aufladung zu erzeugen, wenn mindestens ein Ziel getroffen wird ]"}
MultiLanguageSpellData['de'][1454] = {name = "Aderlass", additional_info = "Sofort\n[q][ Glyphe 'Aderlass' : Belegt Euch mit einem stapelbaren Effekt, der bis Abbruch lang anhält sowie Heilung in Höhe von 15% Eurer gesamten Gesundheit absorbiert, und regeneriert sofort / Regeneriert sofort] (15 * Gesamtgesundheit * 0.01) Mana. [ Glyphe 'Aderlass' : Hält bis Abbruch lang an ]"}
MultiLanguageSpellData['de'][1459] = {name = "Arkane Brillanz", additional_info = "{1% von Grundmana} {30 Meter Reichweite}\nSofort\n[q]Erfüllt das Ziel mit Brillanz, erhöht 1 Stunde lang seine Zaubermacht um 10% und seine kritische Trefferchance um 5%.\n\n Wenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, werden alle Mitglieder den Effekt erhalten."}
MultiLanguageSpellData['de'][1462] = {name = "Wildtierkunde", additional_info = "40 Meter Reichweite\nSofort\n[q]Sammelt Informationen über das Zielwildtier. Der Tooltip zeigt Schaden, Gesundheit, Rüstung, alle Spezialwiderstände und Ernährung an. Zusätzlich wird angezeigt, ob das Tier zähmbar ist und über welche Fähigkeiten die gezähmte Kreatur verfügt."}
MultiLanguageSpellData['de'][1463] = {name = "Schutz des Beschwörers", additional_info = "{Sofort} {25 sek. Abklingzeit}\n[q]Umgibt Euch mit einem magischen Schutz, der 8 Sek. lang bis zu ( 1041 + Zaubermacht * 1.0) Schaden absorbiert. Der absorbierte Schaden stellt bis zu 18% Eures maximalen Manas wieder her.\n\n Wenn dieser Effekt endet, erhaltet Ihr abhängig von der absorbierten Menge 25 Sek. lang um bis zu 15% erhöhten Zauberschaden.\n\nPassiv:\n Erhöht Euren Zauberschaden um 6% und Eure Manaregeneration um 65%. Dieser Effekt ist inaktiv, während der Zauber 'Schutz des Beschwörers' abklingt."}
MultiLanguageSpellData['de'][1464] = {name = "Zerschmettern", additional_info = "{25 Wut} {Nahkampfreichweite}\nSpontanzauber\nBenötigt Nahkampfwaffe\n[q]Zerschmettert den Gegner und fügt ihm so 275% Waffenschaden plus 1246 zu. [ Kolossales Schmettern : Fügt Gegnern, die vom Effekt Eurer Fähigkeit 'Kolossales Schmettern' betroffen sind, zusätzlich 10% Schaden zu ] [ Weitreichende Stöße : Während 'Weitreichende Stöße' aktiv ist, werden 35% des von 'Zerschmettern' verursachten Schadens auch allen anderen Gegnern im Umkreis von 2 Metern zugefügt ]"}
MultiLanguageSpellData['de'][1485] = {name = "Rollender Brocken", additional_info = "Unbegrenzte Reichweite\nWirken in 2 sek.\n[q]Feuert mit einer Distanzwaffe auf das Ziel."}
MultiLanguageSpellData['de'][1490] = {name = "Fluch der Elemente", additional_info = "{4% von Grundmana} {40 Meter Reichweite}\nSofort\n[q]Verflucht das Ziel [ Glyphe 'Fluch der Elemente' : und 2 zusätzliche Ziele in der Nähe ], wodurch der erlittene Magieschaden 5 Min. lang um 5% erhöht wird.\n\nFlüche\nEs kann pro Ziel immer nur jeweils ein Fluch des Hexenmeisters aktiv sein. [ Seelenbrand: Fluch : Seelenbrand:\nEuer Zauber 'Fluch der Elemente' trifft alle Gegner im Umkreis von 10 Metern um Euer Ziel. ]"}
MultiLanguageSpellData['de'][1494] = {name = "Wildtiere aufspüren", additional_info = "Sofort\n[q]Zeigt alle in der Nähe befindlichen Wildtiere auf der Minikarte an."}
MultiLanguageSpellData['de'][1499] = {name = "Eiskältefalle", additional_info = "{Sofort} {30 sek. Abklingzeit}\n[q]Platziert eine Eisfalle, die den ersten sich nähernden Gegner einfriert, wodurch er bis zu 1 Min. lang handlungsunfähig wird [ Glyphe 'Linderung' : zudem werden alle auf den Gegner wirkenden regelmäßigen Effekte entfernt ]. Jeglicher verursachte Schaden wird das Eis brechen. [ Glyphe 'Eiskältefalle' : Das Bewegungstempo des Ziels ists danach 4 Sek. lang um 70% verringert ] [ Glyphe 'Kein Entkommen' : Die kritische Trefferchance aller Eurer Distanzfähigkeiten gegen das eingefrorene Ziel wird um 100% erhöht, solang das Eis nicht gebrochen wurde ] Es kann immer nur jeweils ein Ziel gleichzeitig in Eis eingeschlossen werden. Die Falle bleibt 1 Min. lang bestehen."}
MultiLanguageSpellData['de'][1509] = {name = "GM Only OFF", additional_info = nil}
MultiLanguageSpellData['de'][1513] = {name = "Wildtier ängstigen", additional_info = "{25 Fokus} {30 Meter Reichweite}\nWirken in 1.5 sek.\n[q]Jagt einem Wildtier Angst ein, woraufhin es bis zu 20 Sek. lang voller Furcht wegläuft. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein Wildtier mit dem Furchteffekt versehen werden."}
MultiLanguageSpellData['de'][1515] = {name = "Wildtier zähmen", additional_info = "30 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\n[q]Beginnt mit dem Zähmen eines Wildtiers, damit es Euer Gefährte wird. Falls Ihr die Aufmerksamkeit des Wildtiers aus irgendeinem Grund verlieren solltet, schlägt die Zähmung fehl."}
MultiLanguageSpellData['de'][1516] = {name = "Schnellschuss", additional_info = "5 - 30 Meter Reichweite\n1 min Abklingzeit\nBenötigt Distanzwaffe\n[q]Feuert Eure Waffe sofort ab und verursacht so 5 zusätzlichen Schaden."}
MultiLanguageSpellData['de'][1528] = {name = "Meister befreien", additional_info = "5 Meter Reichweite\nSofort\n[q]Befreit Euren Meister von allen Fesseln."}
MultiLanguageSpellData['de'][1535] = {name = "Feuernova", additional_info = "{13.7% von Grundmana} {100 Meter Reichweite}\n{Sofort} {4 sek. Abklingzeit}\n[q]Zündet alle auf nahe Feinde wirkenden Effekte Eures Zaubers 'Flammenschock', sodass jedes betroffene Ziel eine Flammenwelle ausstößt, welche allen weiteren Zielen im Umkreis von 10 Metern 1 Feuerschaden zufügt."}
MultiLanguageSpellData['de'][1536] = {name = "Langschuss II", additional_info = nil}
MultiLanguageSpellData['de'][1538] = {name = "Laden", additional_info = "20 Meter Reichweite\nWirken in 5 sek.\n[q]Lädt die Rute von Helcular auf, wenn sie an drei zeremoniellen Scheiterhaufen benutzt wird."}
