MultiLanguageSpellData['de'][8024] = {name = "Waffe der Flammenzunge", additional_info = "7% von Grundmana\nSofort\nBenötigt Nahkampfwaffe\n[q]Erfüllt die Waffe des Schamanen mit Feuermagie, die den verursachten Zauberschaden um 7% erhöht. Jeder Treffer verursacht zusätzlich 1 bis 1 Feuerschaden, abhängig vom Waffentempo. Langsamere Waffen verursachen pro Schwung mehr Feuerschaden. Hält 60 Minuten lang an. [ Elemente entfesseln : Das Entfesseln dieser Verzauberung fügt einem feindlichen Ziel 1241 Feuerschaden zu und erhöht den verursachten Schaden des nächsten Feuerzaubers des Schamanen um 30% ]"}
MultiLanguageSpellData['de'][8033] = {name = "Waffe des Frostbrands", additional_info = "7% von Grundmana\nSofort\nBenötigt Nahkampfwaffe\n[q]Erfüllt die Waffe des Schamanen mit Frostmagie. Bei jedem Treffer besteht eine Chance, zusätzlich 42 Frostschaden zu verursachen und das Bewegungstempo des Ziels 8 Sek. lang um 50% zu verringern. Hält 60 Minuten lang an. [ Elemente entfesseln : Das Entfesseln dieser Verzauberung fügt einem gegnerischen Ziel 969 Frostschaden zu und verringert sein Bewegungstempo 5 Sek. lang um 50%. Der Effekt wird verstärkt, wenn das Ziel bereits von einem bewegungseinschränkenden Frosteffekt betroffen ist ]"}
MultiLanguageSpellData['de'][8034] = {name = "Frostbrandangriff", additional_info = "100 Meter Reichweite\nSofort\n[q]Erfüllt die Waffe des Schamanen mit Frostmagie. Bei jedem Treffer besteht eine Chance, zusätzlich 42 Frostschaden zu verursachen und das Bewegungstempo des Ziels 8 Sek. lang um 50% zu verringern. Hält 60 Minuten lang an."}
MultiLanguageSpellData['de'][8040] = {name = "Druidenschlummer", additional_info = "{60 Mana} {30 Meter Reichweite}\nWirken in 2.5 sek.\n[q]Versetzt das feindliche Ziel bis zu 6 Sek. lang in Schlaf. Jegliche feindliche Aktion wird das Ziel wieder aufwecken. Es kann immer nur jeweils ein Ziel in Schlaf versetzt werden."}
