MultiLanguageSpellData['de'][12888] = {name = "Wahnsinn verursachen", additional_info = "30 Meter Reichweite\nSofort\n[q]Treibt ein feindliches Ziel für begrenzte Zeit in den Wahnsinn, erhöht sein Angriffstempo um 50% und seine Bewegung um 80% und lässt es außerdem 6 Sek. lang seine eigenen Verbündeten angreifen."}
