MultiLanguageSpellData['de'][14900] = {name = "Kettenheilung", additional_info = "{150 Mana} {40 Meter Reichweite}\nWirken in 2.5 sek.\n[q]Erfüllt einen verwundeten Verbündeten mit Heilenergie, die sich auf einen anderen in der Nähe befindlichen Verbündeten ausbreitet. Der Zauber wirkt sich auf bis zu 3 Ziele aus, aber die Heilenergie wird bei jedem folgenden Ziel um 50% reduziert."}
