MultiLanguageSpellData['de'][19505] = {name = "Magie verschlingen", additional_info = "{20 Energie} {30 Meter Reichweite}\n{Sofort} {15 sek. Abklingzeit}\n[q]Reinigt 1 nützlichen Magieeffekt von einem Feind. Wird ein Effekt verschlungen, gewinnt der Teufelsjäger 60 Teufelsenergie und er wird um 2115 geheilt.\n\nAutomatisches Wirken:\n Wird auf das aktuelle Ziel des Teufelsjägers gewirkt.\n\n(Mit Rechtsklick umschalten)"}
MultiLanguageSpellData['de'][19506] = {name = "Aura des Volltreffers", additional_info = "[q]Erhöht im Umkreis von 100 Metern die Nahkampf- und Distanzangriffskraft aller Gruppen- und Schlachtzugsmitglieder um 10%."}
MultiLanguageSpellData['de'][19512] = {name = "Salbe auftragen", additional_info = "5 Meter Reichweite\nWirken in 1.3 sek.\nTools: Heilende Tiersalbe\n[q]Heilt ein kränkliches Tier, das mit der Besudelung durch eine Vergiftung infiziert ist."}
MultiLanguageSpellData['de'][19513] = {name = "Blitzschlagwolke", additional_info = "30 Meter Reichweite\n{Sofort} {40 sek. Abklingzeit}\n[q]Lässt eine Blitzschlagwolke entstehen, die 15 Sek. anhält und allen Feinden im ausgewählten Gebiet 28 bis 32 Naturschaden und alle 5 Sek. 42 bis 48 zusätzlichen Schaden zufügt."}
MultiLanguageSpellData['de'][19514] = {name = "Blitzschlagschild", additional_info = "30 Meter Reichweite\n{Sofort} {10 sek. Abklingzeit}\n[q]Umgibt den Zaubernden mit 3 Kugelblitzen, die eine Chance von 50% gewähren, Nahkampf- oder Distanzangreifern Naturschaden zuzufügen. Jedes Mal, wenn der Blitzschlagschild ausgelöst wird, wird ein Kugelblitz aufgezehrt. Der Schild endet nach Ablauf von 10 Min. oder nachdem er 3-mal ausgelöst wurde.\n(Procchance: 50%, 3.5s Abklingzeit)"}
