MultiLanguageSpellData['de'][27585] = {name = "[q3]Schwerer Obsidiangürtel", additional_info = "Wirken in 15 sek.\nTools: Schmiedehammer\nReagenzien:\nKleiner Obsidiansplitter (14), Verzauberter Thoriumbarren (4), Essenz der Erde (2)\n[q3]Schwerer Obsidiangürtel\nWird beim Anlegen gebunden\nTaille Platte\n352 Rüstung\n+25 Stärke\nHaltbarkeit 45 / 45\n60\n[q2]Anlegen: + 6 Alle Widerstandsarten."}
MultiLanguageSpellData['de'][27586] = {name = "[q4]Gezackter Obsidianschild", additional_info = "Wirken in 15 sek.\nTools: Schmiedehammer\nReagenzien:\nGroßer Obsidiansplitter (8), Kleiner Obsidiansplitter (24), Verzauberter Thoriumbarren (8), Essenz der Erde (4)\n[q4]Gezackter Obsidianschild\nWird beim Anlegen gebunden\nSchildhand Schild\n2209 Rüstung\n[q2]+ 9 Ausweichen\nHaltbarkeit 120 / 120\n60\n[q2]Anlegen: + 6 Alle Widerstandsarten.\n[q2]Anlegen: Bei einem Treffer durch einen gegnerischen Zauber besteht eine Chance von 5%, dass der Angreifer 3 Sek. zum Schweigen gebracht wird. (Procchance: 5%, 20s Abklingzeit)"}
MultiLanguageSpellData['de'][27587] = {name = "[q4]Dicke Obsidianbrustplatte", additional_info = "Wirken in 15 sek.\nTools: Schmiedehammer\nReagenzien:\nGroßer Obsidiansplitter (18), Kleiner Obsidiansplitter (40), Verzauberter Thoriumbarren (12), Essenz der Erde (10), Gewaltiger Smaragd (4)\n[q4]Dicke Obsidianbrustplatte\nWird beim Anlegen gebunden\nBrust Platte\n796 Rüstung\n+38 Stärke\n+16 Ausdauer\nHaltbarkeit 165 / 165\n60\n[q2]Anlegen: Bei einem Treffer durch einen Schadenszauber, der unregelmäßigen Schaden zufügt, besteht eine Chance von 30%, 6 Sek. lang einen Zauberschild zu aktivieren, der 300 bis 500 Schaden der entsprechenden Schadenskategorie absorbiert. (Procchance: 30%, 10s Abklingzeit)"}
