MultiLanguageSpellData['de'][30565] = {name = "[q4]Verzauberter Helm des Vorarbeiters", additional_info = "Wirken in 10 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchattenstoff (4), Urmana (12), Urluft (12)\n[q4]Verzauberter Helm des Vorarbeiters\nWird beim Aufheben gebunden\nKopf Stoff\n279 Rüstung\n+70 Ausdauer\n+31 Intelligenz\nHaltbarkeit 100 / 100\nBenötigtIngenieurskunst\n(350)\nBenötigtGobliningenieur\n[q2]Anlegen: +10% Betäubungswiderstand."}
MultiLanguageSpellData['de'][30566] = {name = "[q4]Verstärkter Helm des Vorarbeiters", additional_info = "Wirken in 10 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärteter Adamantitbarren (8), Urerde (12), Urfeuer (12)\n[q4]Verstärkter Helm des Vorarbeiters\nWird beim Aufheben gebunden\nKopf Kette\n596 Rüstung\n+31 Beweglichkeit\n+70 Ausdauer\nHaltbarkeit 100 / 100\nBenötigtIngenieurskunst\n(350)\nBenötigtGobliningenieur\n[q2]Anlegen: Erhöht Eure Chance, Betäubungs- und Desorientierungseffekten zu widerstehen, um 10%."}
