MultiLanguageSpellData['de'][31821] = {name = "Aura der Hingabe", additional_info = "Sofort 3 min Abklingzeit\n[q]Heilig ( Hotfix - Passivfähigkeit )\n Inspiriert alle Gruppen- und Schlachtzugsmitglieder im Umkreis von 40 Metern . Gewährt ihnen Immunität gegen Unterbrechungs- und Stilleeffekte und verringert sämtlichen erlittenen Magieschaden um 20%.\n\n 'Aura der Hingabe' verringert außerhalb von Arenen und Schlachtfeldern zusätzlich den erlittenen körperlichen Schaden um 20%. Hält 6 Sek. lang an.\n\n Schutz, Vergeltung\n Inspiriert [ Glyphe 'Aura der Hingabe' : Euch selbst / alle Gruppen- und Schlachtzugsmitglieder im Umkreis von 40 Metern]. Gewährt [ Glyphe 'Aura der Hingabe' : Euch / ihnen] Immunität gegen Unterbrechungs- und Stilleeffekte und verringert sämtlichen erlittenen Magieschaden um 20%. [ Heilig : 'Aura der Hingabe' verringert außerhalb von Arenen und Schlachtfeldern zusätzlich den erlittenen körperlichen Schaden um 20% ] Hält 6 Sek. lang an."}
MultiLanguageSpellData['de'][31827] = {name = "Heldenhafter Stoß", additional_info = "Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\n[q]Erhöht leicht den Nahkampfschaden des nächsten Angriffs."}
MultiLanguageSpellData['de'][31829] = {name = "Item - Paladin Pvp Set Retribution 4P Bonus", additional_info = "[q]Ihr erhaltet eine Aufladung heiliger Kraft, wenn Ihr direkten Schaden erleidet. Dieser Effekt kann nicht innerhalb von Dungeons oder auf Schlachtzügen und nur einmal alle 8 Sek. auftreten.\n(8s Abklingzeit)"}
