MultiLanguageSpellData['de'][31848] = {name = "Schild des Templers", additional_info = "[q]Verringert die Abklingzeit Eurer Fähigkeit 'Zornige Vergeltung' um 20 Sek. und die Abklingzeit Eures Zaubers 'Wächter der Uralten Könige' um 40 Sek. Zudem erzeugt Euer Zauber 'Göttliche Bitte' 1 heilige Kraft."}
