MultiLanguageSpellData['de'][31866] = {name = "Kreuzzug", additional_info = "[q]Erhöht den verursachten Schaden Eurer Fähigkeiten 'Kreuzfahrerstoß', 'Hammer der Rechtschaffenen' und 'Urteil des Templers' um 10% sowie den Schaden und die Heilung Eures Zaubers 'Heiliger Schock' um 10%. Zudem wird, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt, die Heilung Eures nächsten Wirkens von 'Heiliges Licht' innerhalb von 8 Sek. zusätzlich um 100% erhöht."}
MultiLanguageSpellData['de'][31867] = {name = "Kreuzzug", additional_info = "[q]Erhöht den verursachten Schaden Eurer Fähigkeiten 'Kreuzfahrerstoß', 'Hammer der Rechtschaffenen' und 'Urteil des Templers' um 20% sowie den Schaden und die Heilung Eures Zaubers 'Heiliger Schock' um 20%. Zudem wird, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt, die Heilung Eures nächsten Wirkens von 'Heiliges Licht' innerhalb von 8 Sek. zusätzlich um 200% erhöht."}
MultiLanguageSpellData['de'][31868] = {name = "Dankgebet", additional_info = "[q]Wenn Ihr einen Gegner tötet, der Erfahrung oder Ehre gewährt, wird für die folgenden 8 Sek. Euer nächstes Wirken von 'Lichtblitz' einen kritischen Effekt erzielen.\n(1s Abklingzeit)"}
