MultiLanguageSpellData['de'][33750] = {name = "Angriff des Windzorns", additional_info = "100 Meter Reichweite\nSofort\nBenötigt Einhändig, Schildhand\n[q]Erfüllt die Waffe des Schamanen mit Windmagie. Bei jedem Treffer besteht eine Chance von 20%, zusätzlichen Schaden zuzufügen, der zwei zusätzlichen Angriffen mit zusätzlicher Angriffskraft entspricht. Hält 60 Minuten lang an."}
