MultiLanguageSpellData['de'][39671] = {name = "Regen des Chaos", additional_info = "{15 Mana} {30 Meter Reichweite}\nKanalisiert (Wirken in 6 sek.)\n[q]Ruft einen Schmelzregen herbei, der alle Gegner in einem ausgewählten Gebiet verbrennt und ihnen 6 Sek. lang alle 3 Sek. 138 bis 161 Feuerschaden zufügt."}
MultiLanguageSpellData['de'][39672] = {name = "Fluch der Pein", additional_info = "30 Meter Reichweite\nSofort\n[q]Verflucht einen Feind mit Pein und fügt 30 Sek. lang alle 3 Sek. Schattenschaden zu. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein."}
