MultiLanguageSpellData['de'][47530] = {name = "Borke der Wanderer", additional_info = "5 Meter Reichweite\nWirken in 3 sek.\n[q]Überreicht sie den Urtumen von Lothalor, um sie gegen die verderbenden Einfluss der Arkanwyrms und die Magien zu schützen, welche die Waldländer durchdringen."}
