MultiLanguageSpellData['de'][51723] = {name = "Dolchfächer", additional_info = "35 Energie\nSofort\n[q]Wirbelt sofort herum und schleudert allen Zielen im Umkreis von 10 Metern einen Klingenregen entgegen, der 1558 körperlichen Schaden verursacht [ Glyphe 'Scharfe Klingen' : und Ziele mit dem Effekt 'Rüstungsschwächung' belegt ]. Dieser Angriff hat eine Chance, Eure Ziele zu einer normalen Rate zu vergiften. Gewährt 1 Combopunkt, wenn Ihr ein Ziel trefft, auf dem bereits Eure Combopunkte aktiv sind."}
MultiLanguageSpellData['de'][51725] = {name = "Arkane Explosion", additional_info = "Sofort\n[q]Lässt eine Druckwelle aus Magie entstehen und fügt in der Nähe befindlichen Feinden Arkanschaden zu."}
