MultiLanguageSpellData['de'][51729] = {name = "Segen von Zim'Torga", additional_info = "10 Meter Reichweite\nSofort\n[q]Belegt das freundliche Ziel mit einem Segen, der 1 Stunde lang seine gesamten Werte um 10% erhöht. Auf das Gebiet von Zul'Drak beschränkt."}
MultiLanguageSpellData['de'][51730] = {name = "Waffe der Lebensgeister", additional_info = "10.5% von Grundmana\nSofort\nBenötigt Nahkampfwaffe\n[q]Erfüllt die Waffe des Schamanen mit der Kraft des Lebens. Erhöht die durch Zauber hervorgerufene Heilung um 110 und jede Heilung hat eine Chance von bis zu 20%, den Effekt 'Lebensgeister' auszulösen, der das Ziel im Verlauf von 12 Sek. um zusätzlich 4376 Gesundheit heilt. Auf Ziele mit weniger als 35% Gesundheit gewirkte direkte Einzelzielheilzauber lösen diesen Effekt immer aus. Hält 60 Minuten lang an. [ Elemente entfesseln : Das Entfesseln dieser Verzauberung heilt ein verbündetes Ziel um 3154 und erhöht den Effekt der nächsten direkten Heilung oder von 'Heilender Regen' des Schamanen um 30% ]"}
