MultiLanguageSpellData['de'][53341] = {name = "Rune des schwarzen Gletschers", additional_info = "Wirken in 5 sek.\n[q]Prägt eine Rune in Eure Runenwaffe, die eine Chance besitzt, den Schaden Eurer nächsten 2 Zauber, die Frost- und Schattenschaden verursachen, um 20% zu erhöhen. Für das Umschmieden Eurer Runenwaffe benötigt Ihr eine der Runenschmieden in der Schwarzen Festung."}
MultiLanguageSpellData['de'][53342] = {name = "Rune des Zauberberstens", additional_info = "Wirken in 5 sek.\n[q]Prägt eine Rune in Eure zweihändige Runenwaffe, die 4% jeglichen Zauberschadens abwehrt und die Dauer von Stilleeffekten um 50% verringert. Für das Umschmieden Eurer Runenwaffe benötigt Ihr eine der Runenschmieden in der Schwarzen Festung."}
MultiLanguageSpellData['de'][53343] = {name = "Rune des schneidenden Eises", additional_info = "Wirken in 5 sek.\n[q]Prägt eine Rune in Eure Runenwaffe, die 2% zusätzlichen Waffenschaden als Frostschaden verursacht und die Verletzlichkeit von Zielen gegen Eure Frostangriffe erhöht. Für das Umschmieden Eurer Runenwaffe benötigt Ihr eine der Runenschmieden in der Schwarzen Festung."}
MultiLanguageSpellData['de'][53344] = {name = "Rune des gefallenen Kreuzfahrers", additional_info = "Wirken in 5 sek.\n[q]Prägt eine Rune in Eure Runenwaffe, die eine Chance besitzt, Euch um 3% zu heilen und Eure gesamte Stärke 15 Sek. lang um 15% zu erhöhen. Für das Umschmieden Eurer Runenwaffe benötigt Ihr eine der Runenschmieden in der Schwarzen Festung."}
