MultiLanguageSpellData['de'][53503] = {name = "Schwert des Lichts", additional_info = "[q]Erhöht Euren mit Zweihandwaffen verursachten Schaden um 30%.\n\n Eure Zaubermacht entspricht 50% Eurer Angriffskraft und Ihr profitiert nicht mehr von anderen Zaubermachtquellen.\n\n Gewährt alle 2 Sek. 6% Eures maximalen Manas.\n\n Erhöht die von 'Wort der Herrlichkeit' hervorgerufene Heilung um 60% sowie die von 'Lichtblitz' hervorgerufene Heilung um 100%."}
MultiLanguageSpellData['de'][53504] = {name = "Flackernde Flammen", additional_info = "Sofort\n[q]Verursacht 24 Sek. lang alle 3 Sekunden 200 Feuerschaden.\n Kühlender Nebel verringert diesen Effekt."}
MultiLanguageSpellData['de'][53508] = {name = "Marderbiss", additional_info = "Nahkampfreichweite\n{Sofort} {10 sek. Abklingzeit}\n[q]Ein wilder Angriff, der [1 + ((Fernkampfangriffskraft * 0.40) * 0.10)] Schaden verursacht. Euer Tier kann diesen Angriff ausführen, nachdem es einen kritischen Treffer erzielt hat. Kann nicht geblockt oder pariert und ihm kann nicht ausgewichen werden.\n(7s Abklingzeit)"}
MultiLanguageSpellData['de'][53509] = {name = "Hämmern", additional_info = "Sofort\n[q]Bäumt sich auf und bricht auf alle Feinde innerhalb von 15 Metern vor dem Zaubernden hernieder, verursacht 9425 bis 10575 Schaden und stampft alle Ziele 6 Sek. lang in den Boden."}
