MultiLanguageSpellData['de'][53534] = {name = "Eisketten", additional_info = "20 Meter Reichweite\nSofort\n[q]Friert das Ziel 3 Sek. lang fest. Während dieser Zeit gilt das Ziel als eingefroren. Nach dem Ausbruch aus den Ketten erhält das Ziel pro Sekunde 10% seines Bewegungstempos zurück."}
MultiLanguageSpellData['de'][53536] = {name = "Heulende Böe", additional_info = "20 Meter Reichweite\nSofort\n[q]Weht dem Ziel eine eisige Böe entgegen, die allen Zielen innerhalb von 10 Metern 278 bis 302 Frostschaden zufügt. Gefrorene Ziele erleiden dreifachen Schaden."}
MultiLanguageSpellData['de'][53539] = {name = "Eisstachel", additional_info = nil}
MultiLanguageSpellData['de'][53549] = {name = "Eisige Berührung", additional_info = "20 Meter Reichweite\nSofort\n[q]Verursacht 86 bis 92 Frostschaden (modifiziert durch Angriffskraft) und verringert bis Abbruch lang das Nahkampfangriffs-, Distanzangriffs- und Zaubertempo des Ziels um 86 bis 92%."}
MultiLanguageSpellData['de'][53550] = {name = "Gedankenfrost", additional_info = "Nahkampfreichweite\nSofort\n[q]Die Gedanken des Ziels werden von einer Kälte geschlagen, die 100 Frostschaden verursacht (modifiziert durch Angriffskraft). Das Wirken von Zaubern wird unterbrochen sowie 4 Sek. lang verhindert, dass Zauber dieser Art gewirkt werden können."}
MultiLanguageSpellData['de'][53551] = {name = "Heilige Läuterung", additional_info = "[q]Euer Zauber 'Läuterung' bannt nun auch Magieeffekte.\n[q]Modifies Effect #3's Value +100:\nLäuterung"}
MultiLanguageSpellData['de'][53563] = {name = "Flamme des Glaubens", additional_info = "60 Meter Reichweite\n{Sofort} {3 sek. Abklingzeit}\n[q]Das Ziel wird für alle Gruppen- und Schlachtzugsmitglieder im Umkreis von 60 Metern zu einer Flamme des Glaubens.\n\n Es kann immer nur ein Ziel zur gleichen Zeit eine Flamme des Glaubens sein.\n\nFlamme des Glaubens\n Wenn Ihr Ziele mit Eurem Zauber 'Heiliges Licht' heilt, wird die Flamme ebenfalls um 100% des geheilten Wertes geheilt. Eure Zauber 'Heiliges Strahlen', 'Licht der Morgendämmerung', 'Hammer des Lichts' und 'Heiliges Prisma' heilen die Flamme um 15% des Wertes. Alle anderen Heilzauber heilen die Flamme um 50% des geheilten Wertes."}
MultiLanguageSpellData['de'][53570] = {name = "Zehrende Kälte", additional_info = "10 Meter Reichweite\nSofort\n[q]Entfesselt alle verfügbare Runenmacht, um der Erde unter dem Todesritter jegliche Wärme zu entziehen. Feinde innerhalb von 10 Metern werden in Eis eingeschlossen, das für 1 Sek. pro 5 Runenmacht jegliche ihrer Aktionen verhindert. Feinde zählen als eingefroren, jeglicher verursachte Schaden unterbricht den Effekt."}
MultiLanguageSpellData['de'][53576] = {name = "Lichtenergie", additional_info = "[q]Kritische Effekte Eures Zaubers 'Heiliger Schock' verringern die Zauberzeit Eures nächsten Wirkens von 'Heiliges Licht', 'Göttliches Licht' oder 'Heiliges Strahlen' um 1.50 Sek."}
MultiLanguageSpellData['de'][53592] = {name = "Vom Licht behütet", additional_info = "[q]Erhöht Eure gesamte Ausdauer um 25% und Eure Blockchance um 10%.\n\n Verringert die Chance, dass Ihr kritische Nahkampftreffer erleidet, um 6%.\n\n Euer Zauber 'Wort der Herrlichkeit' ist nicht mehr von globaler Abklingzeit betroffen.\n\n Eure Zaubermacht entspricht 50% Eurer Angriffskraft und Ihr profitiert nicht mehr von anderen Zaubermachtquellen.\n\n Gewährt Euch alle 2 Sek. 15% Eures maximalen Manas.\n(Procchance: 10%)"}
MultiLanguageSpellData['de'][53595] = {name = "Hammer der Rechtschaffenen", additional_info = "{3% von Grundmana} {Nahkampfreichweite}\n{Sofort} {4.5 sek. Abklingzeit}\nBenötigt Nahkampfwaffe\n[q]Schlägt mit einem Hammer aus Licht nach dem Ziel, der ihm 20% Waffenschaden zufügt und eine Welle aus Licht auslöst, die Gegnern im Umkreis von 8 Metern 35% Waffenschaden als Heiligschaden zufügt und den Effekt 'Kampfesmüdigkeit' verursacht. Gewährt eine Aufladung heiliger Kraft.\n\n Kampfesmüdigkeit\n Demoralisiert das Ziel und verringert den von ihm verursachten körperlichen Schaden 30 Sek. lang um 10%."}
MultiLanguageSpellData['de'][53599] = {name = "Ungeziefer der Anub'ar beschwören", additional_info = nil}
MultiLanguageSpellData['de'][53600] = {name = "Schild der Rechtschaffenen", additional_info = "3 Heilige Kraft Nahkampfreichweite\n{Spontanzauber} {1.5 sek. Abklingzeit}\n[q]Verpasst dem Ziel sofort einen heftigen Schlag mit Eurem Schild, der 836 Heiligschaden verursacht. Außerdem wird 3 Sek. lang Euer erlittener körperlicher Schaden um (25 *- 1 ; Min 30, Max 80)% verringert und der Effekt 'Bastion der Herrlichkeit' hervorgerufen.\n\nBastion der Herrlichkeit\nErhöht die Heilwirkung Eures nächsten Wirkens von [ Ewige Flamme : 'Ewige Flamme' / 'Wort der Herrlichkeit'], wenn der Zauber auf Euch selbst gewirkt wird, um 10%. [ Selbstloser Heiler : 'Selbstloser Heiler' erhöht ebenfalls Eure Selbstheilung mit 'Lichtblitz' um 20% pro Stapel ] Bis zu 5-mal stapelbar."}
