MultiLanguageSpellData['de'][56229] = {name = "Glyphe 'Schattenbrand'", additional_info = "[q]Wenn Euer Zauber 'Schattenbrand' ein Ziel nicht tötet, das über 20% Gesundheit oder weniger verfügt, wird seine Abklingzeit sofort abgeschlossen. Dieser Effekt hat eine Abklingzeit von 6 Sek.."}
