MultiLanguageSpellData['de'][56245] = {name = "Festlicher Schokoladenkuchen", additional_info = "5 Meter Reichweite\nWirken in 1 sek.\n[q]Mit Rechtsklick einen kerzenbeladenen Schokoladenkuchen aufstellen, der für bis zu fünf Gruppenmitglieder reicht."}
MultiLanguageSpellData['de'][56246] = {name = "Glyphe 'Teufelswache'", additional_info = "[q]Eure Teufelswache wird sich mit einer zufälligen Waffe der folgenden Arten ausrüsten, die sich in Euren Taschen befindet: Zweihandaxt, Zweihandschwert oder Stangenwaffe."}
