MultiLanguageSpellData['de'][56460] = {name = "Kobaltsplitterbombe", additional_info = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nEine Handvoll Kobaltbolzen (2), Unberechenbarer Sprengauslöser\n(3)\nBenötigtIngenieurskunst\n(330)\n[q2]Benutzen: Fügt Zielen in einem Umkreis von 3 Metern ( 75 * 10) bis ( 100 * 10) Feuerschaden zu und macht sie 3 Sek. lang handlungsunfähig. Jeglicher Schaden wird den Effekt abbrechen. (1 Min Abklingzeit)"}
MultiLanguageSpellData['de'][56461] = {name = "Klingenhacke", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nKobaltbarren (5)\n[q]\"Kann als Spitzhacke oder Kürschnermesser verwendet werden.\""}
MultiLanguageSpellData['de'][56462] = {name = "Gnomisches Armeemesser", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nSaronitbarren (10), Kürschnermesser , Spitzhacke , Schmiedehammer\n[q2]Benutzen: Ein Ingenieur mit einer Fähigkeit von mindestens 350 kann die Batterien des Messers überladen, um zu versuchen, einen toten Verbündeten ins Leben zurückzurufen. Kann nicht im Kampf verwendet werden. (30 Min Abklingzeit)\n[q2]+10 Bergbau\n +10 Kräuterkunde\n +10 Kürschnern\n[q]\"Beinhaltet einen gyromatischen Mikroregler, einen Bogenlichtschraubenschlüssel, Nasenbohrer, Schmiedehammer, Rückenkratzer und ein Kreiseldings.\""}
MultiLanguageSpellData['de'][56463] = {name = "Explosiver Lockvogel", additional_info = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nFroststoff , Unberechenbarer Sprengauslöser (3)\n(5)\nBenötigtIngenieurskunst\n(350)\n[q2]Benutzen: Beschwört einen Lockvogel, der explodiert, wenn er angegriffen wird, und Gegnern 1440 bis 2160 körperlichen Schaden zufügt. Hält 3 Min. lang an oder bis er explodiert. (2 Min Abklingzeit)\n[q]\"Warnhinweis: Kann vorzeitig explodieren, wenn elektromagnetischem Puls ausgesetzt.\""}
