MultiLanguageSpellData['de'][56465] = {name = "[q3]Mechanische Schneebrille", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nSaronitbarren (8), Boreanisches Leder (2), Äonenschatten\n[q3]Mechanische Schneebrille\nWird beim Anlegen gebunden\nKopf Stoff\n581 Rüstung\n[q2]<Zufällige Verzauberung>\nHaltbarkeit 85 / 85\nBenötigtIngenieurskunst\n(400)\n[q2]Anlegen: Vor Kälte geschützt. Euer Frostwiderstand ist um 20 erhöht."}
MultiLanguageSpellData['de'][56466] = {name = "[q3]Überschallbooster", additional_info = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nFroststahlröhre (2), Überladener Kondensator (4), Eine Handvoll Kobaltbolzen (2)\n[q3]Überschallbooster\nWird beim Anlegen gebunden\nSchmuck\n+81 Ausdauer\nBenötigtIngenieurskunst\n(390)\n[q2]Anlegen: In manchen Fällen schärft der Lärm von Nahkämpfen Euer Schallbewusstsein und erhöht 10 Sek. lang Eure Angriffskraft um 498 . Dieser Effekt kann pro Minute nur einmal auftreten. (Procchance: 35%, 50s Abklingzeit)"}
MultiLanguageSpellData['de'][56467] = {name = "[q3]Lärmmaschine", additional_info = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nFroststahlröhre (2), Überladener Kondensator (2), Eine Handvoll Kobaltbolzen (8)\n[q3]Lärmmaschine\nWird beim Anlegen gebunden\nSchmuck\n+54 Intelligenz\nBenötigtIngenieurskunst\n(390)\n[q2]Anlegen: Nahkampfangriffe auf Euch haben eine Chance, einen Schallschild zu beschwören, der 1273 Schaden absorbiert. Dieser Effekt kann nur einmal pro Minute auftreten. (Procchance: 50%, 50s Abklingzeit)"}
MultiLanguageSpellData['de'][56468] = {name = "Kiste voller Bomben", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nSaronitbarren (5), Unberechenbarer Sprengauslöser\n[q]\"Beinhaltet Saronitbomben. Jede Menge Saronitbomben.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageSpellData['de'][56469] = {name = "[q3]Gnomischer Blitzgenerator", additional_info = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nTitanbarren (2), Saronitbarren (8), Äonenwasser (2), Äonenluft (2)\n[q3]Gnomischer Blitzgenerator\nWird beim Aufheben gebunden\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 84.\nBenötigtIngenieurskunst\n(425)\n[q2]Benutzen: Erzeugt einen Blitzstrahl, der einen Feind für 1953 Naturschaden trifft. Das ganze Gehäuse des Geräts ist aus Metall... (1 Min Abklingzeit)\n[q]\"Garantiert sicher!\""}
MultiLanguageSpellData['de'][56470] = {name = "[q3]Sonnenzielfernrohr", additional_info = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nFroststahlröhre , Sonnenkristall , Herbstglimmer\n[q3]Sonnenzielfernrohr\n70\n[q2]Benutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht das Distanzangriffstempo um 40 .\n\n Durch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden."}
