MultiLanguageSpellData['de'][56473] = {name = "[q3]Gnomische Röntgenbrille", additional_info = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nTitanbarren (6), Traumsplitter (2), Eine Handvoll Kobaltbolzen (2)\n[q3]Gnomische Röntgenbrille\nWird beim Aufheben gebunden\nSpielzeug\nBenötigtIngenieurskunst\n(350)\nBenötigtGnomeningenieur\n[q2]Benutzen: Ermöglicht es Euch, Spieler ohne Kleidung und Rüstung zu sehen."}
