MultiLanguageSpellData['de'][56837] = {name = "Frostblitz", additional_info = "90 Mana\nWirken in 3 sek.\n[q]Fügt in der Nähe befindlichen Gegnern Frostschaden zu und verringert 4 Sek. lang ihr Bewegungstempo."}
