MultiLanguageSpellData['de'][56844] = {name = "Glyphe 'Rückzug'", additional_info = "[q]Erhöht die Rückstoßentfernung von 'Rückzug'.\n[q]Modifies Effect #1's Value +50%:\nRückzug"}
