MultiLanguageSpellData['de'][56849] = {name = "Glyphe 'Schlangenfalle'", additional_info = "[q]Die von Eurer Schlangenfalle beschworenen Schlangen erleiden durch Flächeneffekte 90% weniger Schaden."}
