MultiLanguageSpellData['de'][56854] = {name = "Gegentritt", additional_info = "Nahkampfreichweite\nSofort\n[q]Ein schneller Tritt, der einem einzelnen Gegner 275 Schaden zufügt. Er unterbricht außerdem das Wirken von Zaubern und verhindert 4 Sek. lang, dass weitere Zauber dieser Art gewirkt werden."}
MultiLanguageSpellData['de'][56855] = {name = "Wirbelschlag", additional_info = "Sofort\nBenötigt Nahkampfwaffe\n[q]Führt einen wirbelnden Angriff durch, der allen in der Nähe befindlichen Feinden Waffenschaden plus 150% zufügt und sie zurückstößt."}
MultiLanguageSpellData['de'][56858] = {name = "Flammenstoß", additional_info = "{260 Mana} {30 Meter Reichweite}\nWirken in 3 sek.\n[q]Lässt eine Flammensäule niedergehen, die alle Feinde in einem ausgewählten Gebiet verbrennt und ihnen 8 Sek. lang alle 2 Sek. zusätzlichen Schaden zufügt."}
