MultiLanguageSpellData['de'][56936] = {name = "Blizzard", additional_info = "{200 Mana} {40 Meter Reichweite}\nKanalisiert (Wirken in 6 sek.)\n[q]Ruft einen Blizzard herbei, der 6 Sek. lang anhält und Feinden im ausgewählten Gebiet alle 2 Sek. 2000 Frostschaden zufügt."}
MultiLanguageSpellData['de'][56937] = {name = "Eisdorn", additional_info = "Unbegrenzte Reichweite\nWirken in 0.5 sek.\n[q]Fügt einem feindlichen Ziel 875 bis 1125 Frostschaden zu. Bei eingefrorenen Zielen wird dreifacher Schaden zugefügt."}
