MultiLanguageSpellData['de'][56943] = {name = "Glyphe 'Rasende Regeneration'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nNach der Aktivierung von 'Rasende Regeneration' sind auf Euch gewirkte Heileffekte 6 Sek. lang 40% mächtiger. Allerdings kostet Eure 'Rasende Regeneration' nun immer 50 Wut und wandelt Wut nicht mehr in Gesundheit um."}
MultiLanguageSpellData['de'][56944] = {name = "Glyphe 'Omen'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend kein Finsterniszustand aktiv ist, gewähren Euch die folgenden Fähigkeiten 10 Solar- oder Lunarenergie: 'Wucherwurzeln', 'Wirbelsturm', 'Feenfeuer', 'Feenschwarm', 'Massenumschlingung', 'Taifun', 'Desorientierendes Gebrüll', 'Ursols Vortex' und 'Mächtiger Hieb'."}
MultiLanguageSpellData['de'][56945] = {name = "Glyphe 'Heilende Berührung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Euren Zauber 'Heilende Berührung' wirkt, wird die Abklingzeit von 'Schnelligkeit der Natur' um 3 Sek. verringert."}
MultiLanguageSpellData['de'][56946] = {name = "Glyphe 'Hurrikan'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Zauber 'Hurrikan' und 'Astralsturm' verringern nun das Bewegungstempo betroffener Ziele um 50%."}
MultiLanguageSpellData['de'][56947] = {name = "Glyphe 'Anregen'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Euer Zauber 'Anregen' auf ein anderes Ziel gewirkt wird, als auf Euch selbst, profitieren beide Parteien davon. Der Effekt wird jedoch um 40% verringert."}
MultiLanguageSpellData['de'][56948] = {name = "Glyphe 'Orca'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\n[q9]Geringe Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Wassergestalt erscheint nun als Orca."}
MultiLanguageSpellData['de'][56949] = {name = "Glyphe 'Erblühen'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\n'Erblühen' wird durch Wildpilze verursacht anstatt durch 'Rasche Heilung'. 'Erblühen' hält so lange an, wie ein Wildpilz aktiv ist. Erhöht die durch 'Rasche Heilung' hervorgerufene Heilung um 20%."}
MultiLanguageSpellData['de'][56950] = {name = "Glyphe 'Hirsch'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Geringe Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Reisegestalt kann nun Gruppenmitgliedern als Reittier dienen. Diese Glyphe wird deaktiviert, solange Glyphe 'Gepard' aktiv ist."}
MultiLanguageSpellData['de'][56951] = {name = "Glyphe 'Wildes Brüllen'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Wildes Brüllen' kann nun gänzlich ohne Compopunkte eingesetzt werden, was zu einer Dauer von 12 Sek. führt."}
MultiLanguageSpellData['de'][56952] = {name = "Glyphe 'Anspringen'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Reichweite Eurer Fähigkeit 'Anspringen' um 8 Meter."}
MultiLanguageSpellData['de'][56953] = {name = "Glyphe 'Wiedergeburt'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nSpieler, die durch Euren Zauber 'Wiedergeburt' ins Leben zurückgerufen wurden, kehren mit 100% Gesundheit zurück."}
MultiLanguageSpellData['de'][56954] = {name = "Glyphe 'Nachwachsen'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die kritische Trefferchance Eures Zaubers 'Nachwachsen' um 40%, entfernt aber den regelmäßigen Heileffekt."}
MultiLanguageSpellData['de'][56955] = {name = "Glyphe 'Verjüngung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Euer Zauber 'Verjüngung' auf drei oder mehr Zielen aktiv ist, wird die Zauberzeit von 'Pflege' um 30% verringert."}
MultiLanguageSpellData['de'][56956] = {name = "Glyphe 'Schleichen'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Einschränkung des Bewegungstempos beim Schleichen um 100%."}
MultiLanguageSpellData['de'][56957] = {name = "Glyphe 'Schreddern'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend 'Berserker' oder 'Tigerfuror' aktiv sind, hat 'Schreddern' keine Positionsvoraussetzungen mehr."}
MultiLanguageSpellData['de'][56958] = {name = "Glyphe 'Schädelstoß'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Unterbrechungsdauer Eurer Fähigkeit 'Schädelstoß' um 2 Sek., erhöht jedoch die Abklingzeit um 5 Sek."}
MultiLanguageSpellData['de'][56959] = {name = "Glyphe 'Gelenkte Sterne'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Sternenregen' trifft nur Ziele, die von Euren Zaubern 'Mondfeuer' oder 'Sonnenfeuer' betroffen sind."}
MultiLanguageSpellData['de'][56960] = {name = "Glyphe 'Stampede'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr könnt 'Anstachelndes Gebrüll' nun außerhalb von Katzen- oder Bärengestalt einsetzen."}
MultiLanguageSpellData['de'][56961] = {name = "Glyphe 'Zermalmen'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Zermalmen' trifft 1 zusätzliches Ziel für 50% des Schadens."}
MultiLanguageSpellData['de'][56963] = {name = "Glyphe 'Griff der Natur'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eures Zaubers 'Griff der Natur' um 45 Sek."}
MultiLanguageSpellData['de'][56965] = {name = "Glyphe 'Sterne'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Geringe Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Mondkingestalt erscheint nun als Astralgestalt, gewährt weiterhin dieselben Boni, lässt Euch aber als astral verstärkte Version Eurer normalen, humanoiden Gestalt erscheinen."}
MultiLanguageSpellData['de'][56966] = {name = "Grenzwarnung", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Euer Fahrzeug befindet sich außerhalb der Begrenzung. Kehrt sofort auf das Schlachtfeld zurück!"}
MultiLanguageSpellData['de'][56969] = {name = "Arkanschlag", additional_info = "30 Meter Reichweite\nWirken in 2.5 sek.\n[q]Überzieht einen Feind mit Energie und verursacht 4375 bis 5625 Arkanschaden. Jedes Mal, wenn Ihr 'Arkanschlag' wirkt, verringert sich die Zauberzeit. Dieser Effekt ist bis zu 5-mal stapelbar und hält 8 Sek. lang an."}
MultiLanguageSpellData['de'][56971] = {name = "Glyphe 'Ungebundenes Mana'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Geringe Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Manaedelstein stellt nun statt mit sofortiger Wirkung im Verlauf von 6 Sek. Mana wieder her."}
MultiLanguageSpellData['de'][56972] = {name = "Glyphe 'Arkane Explosion'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den Radius von 'Arkane Explosion' um 5 Meter."}
MultiLanguageSpellData['de'][56973] = {name = "Glyphe 'Blinzeln'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Teleportdistanz Eures Zaubers 'Blinzeln' um 8 Meter."}
