MultiLanguageSpellData['de'][56975] = {name = "Glyphe 'Einäschern'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den direkten Schaden, die Dauer des regelmäßigen Schadens und die Abklingzeit von 'Einäschern' um 100%."}
MultiLanguageSpellData['de'][56976] = {name = "Glyphe 'Frostnova'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eures Zaubers 'Frostnova' um 5 Sek."}
MultiLanguageSpellData['de'][56978] = {name = "Glyphe 'Momentum'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Geringe Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Blinzeln' teleportiert Euch in die Richtung, in die Ihr Euch bewegt, statt in Eure Blickrichtung."}
MultiLanguageSpellData['de'][56979] = {name = "Glyphe 'Eisblock'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn der Effekt 'Eisblock' abläuft, wird eine kostenlose Frostnova ausgelöst und Ihr seid 3 Sek. lang immun gegenüber allen Zaubern."}
MultiLanguageSpellData['de'][56980] = {name = "Glyphe 'Zersplitterndes Eis'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Eislanze' und Eure Eiszapfen treffen jetzt 1 zusätzliches Ziel und fügen ihm 50% Schaden zu."}
