MultiLanguageSpellData['de'][56983] = {name = "Glyphe 'Schnelle Deplatzierung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Blinzeln' hat jetzt 2 Aufladungen mit einer Aufladungszeit von 15 Sek., befreit Euch aber nicht mehr von Betäubungs- und Bewegungsunfähigkeitseffekten."}
MultiLanguageSpellData['de'][56984] = {name = "Glyphe 'Manaedelstein'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Manaedelstein herbeizaubern' erzeugt nun einen brillanten Manaedelstein, der über bis zu 10 Aufladungen verfügt."}
MultiLanguageSpellData['de'][56986] = {name = "Glyphe 'Kleintierverwandlung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Geringe Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Euer Zauber 'Verwandlung' auf Kleintiere gewirkt wird, hält er 24 Stunden lang an und kann auf mehrere Ziele gewirkt werden."}
MultiLanguageSpellData['de'][56987] = {name = "Glyphe 'Verwandlung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Verwandlung' entfernt zusätzlich alle auf das Ziel wirkenden Effekte, die Schaden über Zeit verursachen."}
MultiLanguageSpellData['de'][56988] = {name = "Glyphe 'Eisige Adern'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Eisige Adern' bewirkt, dass Eure Zauber 'Frostblitz', 'Frostfeuerblitz', 'Eislanze' und der Zauber 'Wasserblitz' Eures Wasserelementars in jeweils 3 kleinere Blitze aufgeteilt werden, die 40% Schaden verursachen, anstatt das Zaubertempo zu erhöhen."}
MultiLanguageSpellData['de'][56989] = {name = "Glyphe 'Zauberraub'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr erfolgreich einen Zauber raubt, werdet Ihr zusätzlich um 5% Eurer maximalen Gesundheit geheilt."}
MultiLanguageSpellData['de'][56990] = {name = "Glyphe 'Fluch aufheben'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den von Euch verursachten Schaden 10 Sek. lang um 5%, wenn Ihr erfolgreich einen Fluch aufgehoben habt."}
MultiLanguageSpellData['de'][56991] = {name = "Glyphe 'Arkane Macht'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Wirkungsdauer und die Abklingzeit von 'Arkane Macht' um 100%."}
MultiLanguageSpellData['de'][56994] = {name = "Glyphe 'Aspekte'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\n[q9]Geringe Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nJedes Mal, wenn Ihr in einen anderen Aspekt wechselt, folgt Euch 15 Sek. lang ein Abbild dieses neuen Aspektes."}
MultiLanguageSpellData['de'][56995] = {name = "Glyphe 'Camouflage'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Camouflage' gewährt Euch nun selbst wenn Ihr Euch bewegt einen Verstohlenheitseffekt, Euer Bewegungstempo wird, während die Fähigkeit aktiv ist, jedoch um 50% verringert."}
MultiLanguageSpellData['de'][56996] = {name = "Glyphe 'Befreiung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Eure Fähigkeit 'Rückzug' nutzt, werdet Ihr um 5% Eurer gesamten Gesundheit geheilt."}
MultiLanguageSpellData['de'][56997] = {name = "Glyphe 'Besserung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Tier heilen' heilt jetzt alle 1 Sek. und heilt zusätzliche 25% der Gesundheit Eures Begleiters im Verlauf seiner Dauer."}
MultiLanguageSpellData['de'][56998] = {name = "Glyphe 'Ablenkender Schuss'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Ablenkender Schuss' lenkt die Aufmerksamkeit des Ziel nun auf Euer Tier statt auf Euch."}
MultiLanguageSpellData['de'][56999] = {name = "Glyphe 'Endloser Zorn'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend 'Zorn des Wildtiers' aktiv ist, kann Euer Tier zwar Schaden erleiden aber nicht getötet werden."}
MultiLanguageSpellData['de'][57000] = {name = "Glyphe 'Abschreckung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die von Eurer Fähigkeit 'Abschreckung' gewährte Schadensverringerung um 20%."}
MultiLanguageSpellData['de'][57001] = {name = "Glyphe 'Rückzug'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Rückstoßentfernung von 'Rückzug'."}
MultiLanguageSpellData['de'][57002] = {name = "Glyphe 'Eiskältefalle'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEndet der Effekt Eurer Eiskältefalle, wird das Bewegungstempo des Ziels 4 Sek. lang um 70% verringert."}
MultiLanguageSpellData['de'][57003] = {name = "Glyphe 'Frostfalle'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den Effektradius Eurer Frostfalle um 2 Meter."}
MultiLanguageSpellData['de'][57004] = {name = "Glyphe 'Irreführung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Eure Fähigkeit 'Irreführung' auf Euer Tier anwendet, wird die Abklingzeit von 'Irreführung' sofort abgeschlossen."}
MultiLanguageSpellData['de'][57005] = {name = "Glyphe 'Sprengfalle'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Sprengfalle verursacht keinen Schaden mehr, sondern stößt stattdessen bei der Explosion der Falle alle im Effektbereich befindlichen Gegner zurück."}
MultiLanguageSpellData['de'][57006] = {name = "Glyphe 'Geistbande'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Euer Begleiter aktiv ist, wird sowohl Eure erhaltene Heilung als auch die Eures Tiers um 10% erhöht."}
MultiLanguageSpellData['de'][57007] = {name = "Glyphe 'Kein Entkommen'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die kritische Distanztrefferchance aller Eurer Angriffe gegen Ziele, die vom Effekt Eurer Eiskältefalle betroffen sind, um 100%."}
MultiLanguageSpellData['de'][57008] = {name = "Glyphe 'Orientierung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den Tempobonus Eures 'Aspekt des Geparden' und 'Aspekt des Rudels' um 8% und erhöht Euer Reittempo um 10%. Die Erhöhung des Reittempos ist nicht mit anderen Effekten stapelbar."}
MultiLanguageSpellData['de'][57009] = {name = "Glyphe 'Wildtier zähmen'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Geringe Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Kanalisierungsdauer von 'Wildtier zähmen' um 4 Sek."}
MultiLanguageSpellData['de'][57010] = {name = "Glyphe 'Schlangenfalle'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nDie von Eurer Schlangenfalle beschworenen Schlangen erleiden durch Flächeneffekte 90% weniger Schaden."}
MultiLanguageSpellData['de'][57011] = {name = "Glyphe 'Gezielter Schuss'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Gezielter Schuss' kann nun aus der Bewegung heraus eingesetzt werden."}
MultiLanguageSpellData['de'][57012] = {name = "Glyphe 'Tier heilen'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nGewährt Eurem Zauber 'Tier heilen' eine Chance von 100%, pro Tick 1 Fluch-, Krankheits-, Magie- oder Gifteffekt von Eurem Tier zu entfernen."}
MultiLanguageSpellData['de'][57014] = {name = "Glyphe 'Linderung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeiten 'Eiskältefalle' und 'Streuschuss' entfernen alle auf das Ziel wirkenden regelmäßigen Schadenseffekte."}
MultiLanguageSpellData['de'][57019] = {name = "Glyphe 'Fokussierter Schild'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Schild des Rächers' trifft 2 Ziele weniger, verursacht jedoch 30% mehr Schaden."}
MultiLanguageSpellData['de'][57020] = {name = "Glyphe 'Unaufhaltsamer Zorn'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Heiliger Zorn' fügt Zielen, die über weniger als 20% Gesundheit verfügen, 50% mehr Schaden zu."}
MultiLanguageSpellData['de'][57021] = {name = "Glyphe 'Mahnwort'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGlyphe 'Mahnende Worte'\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Wort der Herrlichkeit' kann jetzt gegen gegnerische Ziele eingesetzt werden und fügt ihnen Heiligschaden in etwa der Höhe der ansonsten geheilten Menge zu.\n\n Funktioniert nicht mit 'Ewige Flamme'."}
MultiLanguageSpellData['de'][57022] = {name = "Glyphe 'Göttlicher Schutz'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nReduziert den Magieschaden verringernden Effekt Eures Zaubers 'Göttlicher Schutz' auf 20%, lässt ihn dafür aber zusätzlich den erlittenen körperlichen Schaden um 20% verringern."}
MultiLanguageSpellData['de'][57023] = {name = "Glyphe 'Weihe'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr könnt nun den Effektbereich Eures Zaubers 'Weihe' in einem Umkreis von 25 Metern frei platzieren."}
MultiLanguageSpellData['de'][57024] = {name = "Glyphe 'Zornige Vergeltung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Euer Zauber 'Zornige Vergeltung' aktiv ist, werdet Ihr alle 2 Sek. um 1% Eurer maximalen Gesundheit geheilt."}
MultiLanguageSpellData['de'][57025] = {name = "Glyphe 'Blendendes Licht'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Blendendes Licht' stößt Ziele 3 Sek. lang zu Boden, statt sie zu blenden."}
MultiLanguageSpellData['de'][57026] = {name = "Glyphe 'Wort der Herrlichkeit'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den Schaden pro verbrauchter heiliger Kraft nach dem Wirken von 'Wort der Herrlichkeit' oder 'Ewige Flamme' auf ein verbündetes Ziel um 3%. Hält 6 Sek. lang an."}
MultiLanguageSpellData['de'][57027] = {name = "Glyphe 'Heiliger Zorn'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Heiliger Zorn' betäubt auch Elementare, Drachkin und Entartungen."}
MultiLanguageSpellData['de'][57028] = {name = "Glyphe 'Urteil des Templers'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nNachdem Ihr mit 'Urteil des Templers' oder 'Exorzismus' Schaden verursacht habt, erleidet Ihr 6 Sek. lang 10% weniger Schaden."}
MultiLanguageSpellData['de'][57029] = {name = "Glyphe 'Illumination'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nKlassen: Paladin\n25\n[q2]Benutzen:\n[q2]Kritische Effekte Eures Zaubers 'Heiliger Schock' regenerieren sofort 1% Eures Manas, Euer passiver Effekt 'Meditation' regeneriert jedoch 10% weniger Mana."}
MultiLanguageSpellData['de'][57030] = {name = "Glyphe 'Doppelbestrafung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Euren Zauber 'Richturteil' auf ein Ziel wirkt, wird der Schaden des nächsten Wirkens von 'Richturteil' auf ein zweites Ziel um 20% erhöht."}
MultiLanguageSpellData['de'][57031] = {name = "Glyphe 'Göttlichkeit'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Abklingzeit Eures Zaubers 'Handauflegung' um 2 Min., er regeneriert jedoch sofort 10% Eures maximalen Manas."}
MultiLanguageSpellData['de'][57032] = {name = "Glyphe 'Leuchtender Vorreiter'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\n[q9]Geringe Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Klassenreittiere glühen nun mit heiligem Licht."}
MultiLanguageSpellData['de'][57033] = {name = "Glyphe 'Aura der Hingabe'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure 'Aura der Hingabe' wirkt nicht mehr auf Gruppen- und Schlachtzugsmitglieder, die Abklingzeit wird aber um 60 Sek. verringert."}
MultiLanguageSpellData['de'][57034] = {name = "Glyphe 'Gesegnetes Leben'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEs besteht eine Chance von 50%, dass Ihr eine Aufladung heiliger Kraft erhaltet, wenn Ihr mit einem Betäubungs-, Furcht- oder Bewegungsunfähigkeitseffekt belegt werdet.\n\n Dieser Effekt kann nur ein Mal alle 20 Sek. auftreten. (Procchance: 50%, 20s Abklingzeit)"}
MultiLanguageSpellData['de'][57035] = {name = "Glyphe 'Licht der Morgendämmerung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Licht der Morgendämmerung' trifft 2 Ziele weniger, die Heilung pro Ziel wird jedoch um 25% erhöht."}
