MultiLanguageSpellData['de'][57162] = {name = "Glyphe 'Wütende Eile'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Krieger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Ihr Euch in einem Wutzustand befindet, bewegt Ihr Euch 20% schneller."}
MultiLanguageSpellData['de'][57163] = {name = "Glyphe 'Kniesehne'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Krieger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Wut ausgebt, um Eure Fähigkeit 'Kniesehne' einzusetzen, werden die Wutkosten des nächsten Einsatzes von 'Kniesehne' um 100% verringert."}
