MultiLanguageSpellData['de'][57172] = {name = "Glyphe 'Wütender Wind'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Krieger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nTreffer mit Eurer Fähigkeit 'Wütender Schlag' erhöhen den Schaden Eures nächsten Einsatzes von 'Wirbelwind' um 10%. (1s Abklingzeit)"}
MultiLanguageSpellData['de'][57181] = {name = "Glyphe 'Kreis der Heilung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Priester\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Kreis der Heilung' heilt 1 zusätzliches Ziel, seine Manakosten werden jedoch um 35% erhöht."}
MultiLanguageSpellData['de'][57183] = {name = "Glyphe 'Läutern'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Priester\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Läutern' heilt Euer Ziel zusätzlich um 5% seiner maximalen Gesundheit, wenn erfolgreich ein schädlicher Magieeffekt oder eine Krankheit gebannt wurde."}
