MultiLanguageSpellData['de'][57186] = {name = "Glyphe 'Inneres Sanktum'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Priester\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Euer Zauber 'Inneres Feuer' aktiv ist, wird zusätzlich Euer erlittener Zauberschaden um 6% verringert. Zudem wird der Bewegungstempobonus Eures Zaubers 'Innerer Wille' um 6% erhöht."}
MultiLanguageSpellData['de'][57187] = {name = "Glyphe 'Heilige Nova'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Priester\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch den Zauber 'Heilige Nova'.\n\n Löst eine Explosion heiligen Lichts um den Zaubernden aus, die allen Gegnern im Umkreis von 10 Metern 13 Heiligschaden zufügt und bis zu 5 Verbündete in einem Umkreis von 10 Metern um 20 heilt.\n\n Die Heilung wird unter allen geheilten Zielen aufgeteilt. Diese Effekte erzeugen keine Bedrohung."}
MultiLanguageSpellData['de'][57188] = {name = "Glyphe 'Inneres Feuer'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Priester\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die von Eurem Zauber 'Inneres Feuer' gewährte Rüstung um 50%."}
