MultiLanguageSpellData['de'][57243] = {name = "Glyphe 'Welle der Heilung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Schamane\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Welle der Heilung' heilt Euch ebenfalls um 20% des geheilten Wertes, wenn Ihr einen Verbündeten heilt."}
MultiLanguageSpellData['de'][57244] = {name = "Glyphe 'Totemischer Rückruf'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Schamane\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Totemischer Rückruf' erstattet die vollen Manakosten Eurer rückgerufenen Totems zurück."}
MultiLanguageSpellData['de'][57245] = {name = "Glyphe 'Tellurische Ströme'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Schamane\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nLässt durch Euren Zauber 'Blitzschlag' 10 % Eures Manas wiederherstellen, wenn Ihr einen Gegner trefft."}
MultiLanguageSpellData['de'][57246] = {name = "Glyphe 'Wasserschreiter'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Geringe Glyphe\nKlassen: Schamane\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr erlangt automatisch den Effekt 'Wasserwandeln', wenn Ihr Euch in Geisterwolfgestalt befindet."}
MultiLanguageSpellData['de'][57247] = {name = "Glyphe 'Totem der Erdung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Schamane\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nStatt einen Zauber zu absorbieren, reflektiert Euer Totem der Erdung den nächsten Schadenszauber zurück auf den Zaubernden, jedoch wird die Abklingzeit Eures Totems der Erdung um 20 Sek. erhöht."}
MultiLanguageSpellData['de'][57248] = {name = "Glyphe 'Gunst des Geistwandlers'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Schamane\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Dauer Eures Zaubers 'Gunst des Geistwandlers' um 5 Sek."}
MultiLanguageSpellData['de'][57249] = {name = "Glyphe 'Lavapeitsche'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\n[q9]Geringe Glyphe\nKlassen: Schamane\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Lavapeitsche' breitet den Effekt von 'Flammenschock' nicht mehr auf in der Nähe befindliche Gegner aus."}
MultiLanguageSpellData['de'][57250] = {name = "Glyphe 'Kettenbildung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Schamane\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Sprungreichweite Eures Zaubers 'Kettenheilung' um 100%, gibt dem Zauber aber eine Abklingzeit von 2 Sek."}
MultiLanguageSpellData['de'][57251] = {name = "Glyphe 'Wasserschild'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Schamane\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die reaktive Manaregeneration Eures Zaubers 'Wasserschild' nach Angriffen um 50%, die passive Manaregeneration wird aber um 15% verringert."}
MultiLanguageSpellData['de'][57252] = {name = "Glyphe 'Läuterndes Wasser'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Schamane\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr einen schädlichen Zaubereffekt oder Fluch von einem Verbündeten bannt, heilt Ihr das Ziel gleichzeitig um 5% Eurer maximalen Gesundheit."}
MultiLanguageSpellData['de'][57253] = {name = "Glyphe 'Gewitter'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Geringe Glyphe\nKlassen: Schamane\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEntfernt den Rückstoßeffekt von Eurem Zauber 'Gewitter'."}
MultiLanguageSpellData['de'][57257] = {name = "Glyphe 'Hand von Gul'dan'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\n[q9]Geringe Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Hand von Gul'dan' kann auf eine Position gezielt eingesetzt werden."}
MultiLanguageSpellData['de'][57258] = {name = "Glyphe 'Feuersbrunst'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\n'Feuersbrunst' setzt nicht mehr voraus, dass das Ziel von 'Feuerbrand' betroffen ist, um es zu verlangsamen."}
MultiLanguageSpellData['de'][57259] = {name = "Glyphe 'Lebensentzug'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber [ Feuerbrand : 'Feuerbrand' ] 'Verderbnis' heilt Euch um 0.5% Eurer Maximalgesundheit, wenn er [ Feuerbrand : regelmäßigen ] Schaden verursacht."}
MultiLanguageSpellData['de'][57260] = {name = "Glyphe 'Tiefgrüne Sphären'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Geringe Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\n[ Zerstörung : Aktive instabile Funken werden als grüne Sphären dargestellt, die um Euren Charakter wirbeln /\n\nGebrechen, Dämonologie\nEure Seelensplitter werden in grüne Sphären umgewandelt ]"}
MultiLanguageSpellData['de'][57261] = {name = "Glyphe 'Alpträume'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Geringe Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Teufelsross und Euer Schreckensross können übers Wasser hinwegreiten und hinterlassen eine Flammenspur."}
MultiLanguageSpellData['de'][57262] = {name = "Glyphe 'Furcht'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nLässt das Ziel Eures Zaubers 'Furcht' vor Furcht erstarren, anstatt dass es flüchtet."}
MultiLanguageSpellData['de'][57263] = {name = "Glyphe 'Teufelswache'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Geringe Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Teufelswache wird sich mit einer zufälligen Waffe der folgenden Arten ausrüsten, die sich in Euren Taschen befindet: Zweihandaxt, Zweihandschwert oder Stangenwaffe."}
MultiLanguageSpellData['de'][57264] = {name = "Glyphe 'Dämonisches Training'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerbessert die Spezialfähigkeiten Eures Dämons:\n\n Verringert die Zauberzeit des Zaubers 'Feuerblitz' Eures [ Grimoire der Überlegenheit : Teufelswichtels / Wichtels] um 50% und es werden 3 Blitze abgefeuert.\n\n Erhöht die gesamte Rüstung Eures [ Grimoire der Überlegenheit : Leerenfürsten / Leerwandlers] um 10%.\n\n Die Fähigkeit [ Grimoire der Überlegenheit : 'Mesmerisieren' / 'Verführung'] [ Grimoire der Überlegenheit : Eurer Shivarra und Eures Erzinkubus / Eures Succubus und Inkubus] entfernt zusätzlich alle regelmäßigen Schadenseffekte vom Ziel.\n\n Wenn Euer [ Grimoire der Überlegenheit : Beobachter / Teufelsjäger] die Fähigkeit [ Grimoire der Überlegenheit : 'Magie kopieren' / 'Magie verschlingen'] einsetzt, werdet Ihr um die gleiche Menge geheilt.\n\n Erhöht die gesamte Gesundheit [ Grimoire der Überlegenheit : Eures Zornwächters / Eurer Teufelswache] um 20%."}
MultiLanguageSpellData['de'][57265] = {name = "Glyphe 'Lebenslinie'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Geringe Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Lebenslinie' stellt sofort 15% der Gesundheit Eures Dämons wieder her, hat jedoch eine Abklingzeit von 10 Sek."}
MultiLanguageSpellData['de'][57266] = {name = "Glyphe 'Gesundheitsstein'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr gewinnt durch das Nutzen von Gesundheitssteinen 100% mehr Gesundheit, der Effekt wird jedoch zu einer regelmäßigen Heilung, die im Verlauf von 10 Sek. erfolgt."}
MultiLanguageSpellData['de'][57267] = {name = "Glyphe 'Subtilität'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Geringe Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Seelensplitter werden außerhalb des Kampfes nicht mehr angezeigt."}
MultiLanguageSpellData['de'][57268] = {name = "Glyphe 'Fluch der Elemente'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Fluch der Elemente' trifft 2 zusätzliche Ziele in der Nähe."}
MultiLanguageSpellData['de'][57269] = {name = "Glyphe 'Wichtelschwarm'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nBenötigt Dämonologie.\n Lehrt Euch den Zauber 'Wichtelschwarm'.\n\n Wichtelschwarm\nBeschwört 4 Wildwichtel aus dem Wirbelnden Nether, die das Ziel angreifen.\n\n Der passive Effekt von 'Wildwichtel' ist inaktiv, während der Zauber abklingt. Die Abklingzeit von 'Wichtelschwarm' wird von Tempo verringert. Erhöht außerdem die Abklingzeit von 'Wildwichtel' um 4 Sek."}
MultiLanguageSpellData['de'][57270] = {name = "Glyphe 'Verwüstung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nDer Zauber 'Verwüstung' erhält 3 zusätzliche Aufladungen, die Abklingzeit wird jedoch um 35 Sek. erhöht."}
MultiLanguageSpellData['de'][57271] = {name = "Glyphe 'Schattenblitz'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\n[q9]Geringe Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nTeilt Euren Schattenblitz in drei kleinere Geschosse auf."}
MultiLanguageSpellData['de'][57274] = {name = "Glyphe 'Seelenstein'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nSpielercharaktere, die sich durch einen Seelenstein wiederbeleben, erstehen mit 100% Gesundheit auf."}
