MultiLanguageSpellData['de'][58337] = {name = "Glyphe 'Seelenverzehrung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\n[ Gebrechen : Euer Zauber 'Seelendieb' stellt 20% Eurer gesamten Gesundheit wieder her, nachdem Ihr ein Ziel tötet, dass Erfahrung oder Ehre gewährt ] [ Zerstörung : Ihr stellt 20% Eurer gesamten Gesundheit wieder her, wenn Ihr ein Ziel, das Erfahrung oder Ehre gewährt, mit 'Chaosblitz' tötet ]"}
MultiLanguageSpellData['de'][58338] = {name = "Glyphe 'Fluch der Erschöpfung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nKlassen: Hexenmeister\n25\n[q2]Benutzen:"}
MultiLanguageSpellData['de'][58339] = {name = "Glyphe 'Dämon unterwerfen'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\n[q9]Geringe Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Zauberzeit Eures Zaubers 'Dämon unterwerfen' um 50%."}
MultiLanguageSpellData['de'][58340] = {name = "Glyphe 'Auge von Kilrogg'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Geringe Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Auge von Kilrogg ist nicht mehr verstohlen, kann jedoch den Beschwörungskreis Eures dämonischen Zirkels platzieren. Der Hexenmeister muss sich in der Sichtlinie des Auges von Kilrogg befinden, um den dämonischen Zirkel zu platzieren.\n\n Zusätzlich wird das Bewegungstempo des Auges von Kilrogg um 50% erhöht und ihm wird in Gegenden, wo die Nutzung von fliegenden Reittieren möglich ist, Flugfähigkeit verliehen."}
MultiLanguageSpellData['de'][58341] = {name = "Glyphe 'Seelenbrunnen'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Geringe Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEurem Seelenbrunnen entströmt nun ein unheimliches Licht."}
MultiLanguageSpellData['de'][58342] = {name = "Glyphe 'Mystischer Ruf'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Geringe Glyphe\nKlassen: Krieger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeiten 'Schlachtruf' und 'Befehlsruf' bewirken, dass Ihr 1 Sek. lang in der Luft schwebt."}
MultiLanguageSpellData['de'][58343] = {name = "Glyphe 'Markerschütternder Ruf'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Geringe Glyphe\nKlassen: Krieger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeiten 'Schlachtruf' und 'Befehlsruf' versetzen kleine Tiere in Angst und Schrecken."}
