MultiLanguageSpellData['de'][63240] = {name = "Eisenwurzeldornen", additional_info = "40 Meter Reichweite\nSofort\n[q]Aus dem befreundeten Ziel sprießen Dornen, die jedem Angreifer 650 Naturschaden zufügen. Hält 10 Sek. lang an."}
