MultiLanguageSpellData['de'][63242] = {name = "Pflege", additional_info = "{22% von Grundmana} {40 Meter Reichweite}\nWirken in 1.5 sek.\n[q]Heilt ein freundliches Ziel um 23125 bis 26875. Ist ein durch Euch gewirkter Effekt von 'Verjüngung', 'Nachwachsen' oder 'Blühendes Leben' auf dem Ziel aktiv, erhöht sich die Heilung um zusätzliche 20%."}
MultiLanguageSpellData['de'][63247] = {name = "Lebendiger Tsunami", additional_info = "20 Meter Reichweite\nWirken in 1.5 sek.\n[q]Ihr beschwört einen lebendigen Tsunami, der bei Kontakt mit feindlichen Zielen 6013 bis 6987 Naturschaden verursacht sowie 10 Sek. lang alle 2 Sek. 1850 bis 2150 Naturschaden."}
MultiLanguageSpellData['de'][63248] = {name = "Glyphe 'Verbindende Heilung'", additional_info = "[q]Euer Zauber 'Verbindende Heilung' heilt nun ein drittes Ziel innerhalb von 20 Metern, die Manakosten werden jedoch um 35% erhöht."}
