MultiLanguageSpellData['de'][64171] = {name = "Titanischer Sturm", additional_info = "Wirken in 5 sek.\n[q]Kanalisiert einen mächtigen Sturm titanischer Energien, der regelmäßig Feindliche Ziele mit Blitzschlägen trifft, die stark genug sind, um geschwächte unsterbliche Kreaturen zu zerstören."}
