MultiLanguageSpellData['de'][64246] = {name = "Glyphe 'Spiegelnde Klingen'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr einen Zaubertreffer erleidet, während 'Abschreckung' aktiv ist, besteht eine Chance von 100%, dass der Zauber auf den Zaubernden reflektiert wird."}
MultiLanguageSpellData['de'][64247] = {name = "Glyphe 'Totemische Lebenskraft'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Schamane\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Gesundheit Eurer Totems um 5% Eurer maximalen Gesundheit."}
MultiLanguageSpellData['de'][64248] = {name = "Glyphe 'Aderlass'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Aderlass' zehrt keine Gesundheit mehr auf, absorbiert stattdessen jedoch pro Anwendung [(Gesamtgesundheit * 0.15)] erhaltene Heilung. Dieser Effekt ist stapelbar.\n\n Die Absorption hält 30 Sek. lang an."}
MultiLanguageSpellData['de'][64249] = {name = "Glyphe 'Streuschuss'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Jäger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Reichweite der Fähigkeit 'Streuschuss' um 3 Meter."}
MultiLanguageSpellData['de'][64250] = {name = "Glyphe 'Blutige Verbannung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Geringe Glyphe\nKlassen: Hexenmeister\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nDer Effekt Eures Zaubers 'Verbannung' ist nun rot."}
MultiLanguageSpellData['de'][64251] = {name = "Glyphe 'Inquisition'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Effektdauer von 'Inquisition' um 30 Sek., wenn Ihr einem Gegner den Todesstoß versetzt, der Erfahrung oder Ehre gewährt."}
MultiLanguageSpellData['de'][64252] = {name = "Glyphe 'Schildwall'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Krieger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Schildwall' verringert nun den erlittenen Schaden um zusätzlich 20%, ihre Abklingzeit wird jedoch um 2 Min. erhöht."}
