MultiLanguageSpellData['de'][64254] = {name = "Glyphe 'Heiliger Schock'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Paladin\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die gewirkte Heilung Eures Zaubers 'Heiliger Schock' um 50%, erhöht jedoch seinen verursachten Schaden um 50%."}
MultiLanguageSpellData['de'][64255] = {name = "Glyphe 'Siegeswurf'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Krieger\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Reichweite Eurer Fähigkeiten 'Siegesrausch' und 'Bevorstehender Sieg' um 15 Meter."}
MultiLanguageSpellData['de'][64256] = {name = "Glyphe 'Baumrinde'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Druide\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend der Zauber 'Baumrinde' aktiv ist, wird Eure Chance, kritische Treffer zu erleiden, um 25% verringert."}
MultiLanguageSpellData['de'][64257] = {name = "Glyphe 'Tieffrieren'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Tieffrieren' ist nicht mehr von globaler Abklingzeit betroffen, allerdings wird seine Dauer um 1 Sek. verringert."}
