MultiLanguageSpellData['de'][64259] = {name = "Glyphe 'Verbindende Heilung'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Priester\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Verbindende Heilung' heilt nun ein drittes Ziel innerhalb von 20 Metern, die Manakosten werden jedoch um 35% erhöht."}
MultiLanguageSpellData['de'][64260] = {name = "Glyphe 'Verkleiden'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\n[q9]Geringe Glyphe\nKlassen: Schurke\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr einen humanoiden Gegner bestehlt, kopiert Ihr 5 Min. lang sein Erscheinungsbild. Eure Verkleidung schwindet, sobald Ihr den Kampf beginnt."}
MultiLanguageSpellData['de'][64261] = {name = "Glyphe 'Regenguss'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\n[q9]Geringe Glyphe\nKlassen: Schamane\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Kettenheilung' hat nun das Erscheinungsbild von Wasser."}
