MultiLanguageSpellData['de'][64274] = {name = "Glyphe 'Wasserelementar'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Gesundheit Eures Wasserelementars um 40% und ermöglicht es ihm, Zauber während der Bewegung zu wirken. Im Hilfsmodus im Kampf bewirkt der Befehl 'Folgen', dass er in Eurer Nähe bleibt und automatisch 'Wasserblitz' wirkt, wenn ein Ziel in Reichweite gelangt."}
MultiLanguageSpellData['de'][64275] = {name = "Glyphe 'Verlangsamen'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\n[q9]Erhebliche Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Arkanschlag' belegt ein beliebiges Ziel, dem er Schaden zufügt, mit dem Effekt Eures Zaubers 'Verlangsamen', soweit zu diesem Zeitpunkt kein anderes Ziel mit Eurem Zauber 'Verlangsamen' belegt ist."}
MultiLanguageSpellData['de'][64276] = {name = "Glyphe 'Illusion'", additional_info = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\n[q9]Geringe Glyphe\nKlassen: Magier\n25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch die Fähigkeit 'Illusion'.\n\n Lässt Euch 2 Min. lang das Aussehen von jemand anderem annehmen."}
