MultiLanguageSpellData['de'][65807] = {name = "Frostblitz", additional_info = "{13% von Grundmana} {30 Meter Reichweite}\nWirken in 2.5 sek.\n[q]Schleudert einen Frostblitz auf den Feind, der 11563 bis 13437 Frostschaden verursacht und 9 Sek. lang das Bewegungstempo um 40% reduziert."}
MultiLanguageSpellData['de'][65808] = {name = "Entfesselte Nacht", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Die konzentrierte Nacht entfesselt ihre Energien und fügt Gegnern innerhalb von 6 Metern 14625 bis 15375 Nachtschaden zu."}
MultiLanguageSpellData['de'][65809] = {name = "Furcht", additional_info = "{12% von Grundmana} {20 Meter Reichweite}\n{Wirken in} {1.5 sek. 8 sek. Abklingzeit}\n[q]Erfüllt den Feind mit Furcht, woraufhin er bis zu 10 Sek. lang voller Furcht flüchtet. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein einzelnes Ziel mit Furcht erfüllt werden."}
MultiLanguageSpellData['de'][65810] = {name = "Verderbnis", additional_info = "{14% von Grundmana} {30 Meter Reichweite}\nSofort\n[q]Verderbt das Ziel und verursacht 18 Sek. lang insgesamt 30000 Schattenschaden."}
MultiLanguageSpellData['de'][65811] = {name = "Essenz des Lichts", additional_info = nil}
MultiLanguageSpellData['de'][65812] = {name = "Instabiles Gebrechen", additional_info = "{15% von Grundmana} {30 Meter Reichweite}\n{Wirken in} {1.5 sek. 15 sek. Abklingzeit}\n[q]Schattenenergie zerstört langsam das Ziel und verursacht im Verlauf von 15 Sek. 23125 bis 26875 Schaden. Sollte 'Instabiles Gebrechen' gebannt werden, erleidet der Bannende 13875 bis 16125 Schattenschaden und wird 4 Sek. lang zum Schweigen gebracht."}
MultiLanguageSpellData['de'][65813] = {name = "Instabiles Gebrechen", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Sollte 'Instabiles Gebrechen' gebannt werden, erleidet der Bannende 13875 bis 16125 Schattenschaden und wird 5 Sek. lang zum Schweigen gebracht."}
MultiLanguageSpellData['de'][65814] = {name = "Fluch der Pein", additional_info = "{10% von Grundmana} {30 Meter Reichweite}\nSofort\n[q]Verflucht das Ziel mit Pein und fügt 24 Sek. lang insgesamt 42000 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein."}
MultiLanguageSpellData['de'][65815] = {name = "Fluch der Erschöpfung", additional_info = "{6% von Grundmana} {30 Meter Reichweite}\nSofort\n[q]Verringert das Bewegungstempo des Ziels 12 Sek. lang um 50%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein."}
MultiLanguageSpellData['de'][65816] = {name = "Höllenfeuer", additional_info = "64% von Grundmana\nKanalisiert (Wirken in 15 sek.)\n[q]Entzündet den Bereich um den Zaubernden herum, fügt ihm selbst alle 1 Sek. 1500 Feuerschaden zu sowie im gleichen Rhythmus allen in der Nähe befindlichen Feinden 9000 Feuerschaden. Hält 15 Sek. lang an."}
MultiLanguageSpellData['de'][65817] = {name = "Höllenfeuereffekt", additional_info = "Sofort\n[q]Entzündet den Bereich um den Zaubernden herum, fügt ihm selbst alle 1 Sek. 1500 Feuerschaden zu sowie im gleichen Rhythmus allen in der Nähe befindlichen Feinden 9000 Feuerschaden. Hält 15 Sek. lang an."}
MultiLanguageSpellData['de'][65819] = {name = "Sengender Schmerz", additional_info = "{8% von Grundmana} {30 Meter Reichweite}\nWirken in 1.5 sek.\n[q]Fügt dem Ziel sengenden Schmerz zu und verursacht 5490 bis 6510 Feuerschaden."}
MultiLanguageSpellData['de'][65820] = {name = "Todesmantel", additional_info = "{23% von Grundmana} {30 Meter Reichweite}\nSofort 2 min Abklingzeit\n[q]Verursacht 9425 bis 10575 Schattenschaden und das betroffene Ziel läuft 3 Sek. lang voller Entsetzen davon. Der Zaubernde erhält 500% des verursachten Schadens in Gesundheit."}
