MultiLanguageSpellData['de'][65855] = {name = "Insektenschwarm", additional_info = "{8% von Grundmana} {30 Meter Reichweite}\nSofort\n[q]Das feindliche Ziel wird von Insekten umschwärmt, die dessen Trefferchance mit Nahkampf- und Distanzangriffen um 3% verringern und beim Betroffenen über 12 Sek. 22200 bis 25800 Naturschaden verursachen."}
