MultiLanguageSpellData['de'][65858] = {name = "Schild des Lichts", additional_info = "Sofort\n[q]Ein heller Schild schützt die Schwester, absorbiert 1200000 Schaden und verhindert 16 Sek. lang das Unterbrechen von Zaubern."}
MultiLanguageSpellData['de'][65859] = {name = "Wirbelsturm", additional_info = "{8% von Grundmana} {20 Meter Reichweite}\n{Wirken in} {1.5 sek. 6 sek. Abklingzeit}\n[q]Wirbelt das Ziel bis zu 6 Sek. lang in die Luft. Während dieser Zeit ist es handlungsunfähig, aber auch unverwundbar. Es kann immer nur ein Ziel gleichzeitig von Eurem Zauber 'Wirbelsturm' betroffen sein."}
MultiLanguageSpellData['de'][65860] = {name = "Baumrinde", additional_info = "Sofort 1 min Abklingzeit\n[q]Die Haut des Druiden wird hart wie Rinde. Jeglicher erlittene Schaden wird um 40% verringert. Kann auch gewirkt werden, wenn man betäubt, eingefroren, handlungsunfähig oder in Schlaf versetzt worden ist oder sich fürchtet. In allen Gestalten nutzbar. Hält 12 Sek. lang an."}
