MultiLanguageSpellData['de'][66034] = {name = "Kandierte Süßkartoffel", additional_info = "Wirken in 2 sek.\nReagenzien:\nSüßkartoffel aus Mulgore , Honig , Herbstliche Gewürze\nBenötigtPilgerfreudenfest\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Tempo und Ausdauer werden 1 Stunde lang um [floor(cond($GT( 90, 15), 90 - 15, 0) * 0.8) + 4] erhöht."}
MultiLanguageSpellData['de'][66035] = {name = "Moosbeerenchutney", additional_info = "Wirken in 2 sek.\nReagenzien:\nSäuerliche Moosbeeren vom Südstrom , Honig\n(0)\nBenötigtPilgerfreudenfest\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und 1 Stunde lang Eure Zaubermacht um [floor(cond($GT( 90, 15), 90 - 15, 0) * 0.6616) + 4] und Eure Ausdauer um [floor(cond($GT( 90, 15), 90 - 15, 0) * 0.554) + 4] erhöht."}
MultiLanguageSpellData['de'][66036] = {name = "Kürbiskuchen", additional_info = "Wirken in 2 sek.\nReagenzien:\nReifer Tirisfalkürbis , Honig\nBenötigtPilgerfreudenfest\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und 1 Stunde lang Eure Willenskraft und Ausdauer um [floor(cond($GT( 90, 15), 90 - 15, 0) * 0.554) + 4] erhöht."}
MultiLanguageSpellData['de'][66037] = {name = "Langsam gerösteter Truthahn", additional_info = "Wirken in 2 sek. 2\nReagenzien:\nWilder Truthahn , Honig (2), Herbstliche Gewürze\nBenötigtPilgerfreudenfest\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und 1 Stunde lang Eure Angriffskraft um [floor(cond($GT( 90, 15), 90 - 15, 0) * 1.108) + 8] und Eure Ausdauer um [floor(cond($GT( 90, 15), 90 - 15, 0) * 0.554) + 4] erhöht."}
MultiLanguageSpellData['de'][66038] = {name = "Gewürzbrotfüllung", additional_info = "Wirken in 2 sek.\nReagenzien:\nGewürzbrot , Herbstliche Gewürze\nBenötigtPilgerfreudenfest\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Trefferwert und Ausdauer werden 1 Stunde lang um [floor(cond($GT( 90, 15), 90 - 15, 0) * 0.554) + 4] erhöht."}
