MultiLanguageSpellData['de'][73680] = {name = "Elemente entfesseln", additional_info = "{8.2% von Grundmana} {40 Meter Reichweite}\n{Sofort} {15 sek. Abklingzeit}\n[q]Fokussiert die Elementarkraft, die in der Bewaffnung des Schamanen gebündelt ist und setzt sie frei. Der konzentrierte Effekt entspricht der entfesselten Verzauberung. [ Beidhändigkeit : Wenn beide Waffen mit der gleichen Verzauberung versehen sind, wird nur eine entfesselt werden ]\n Die Einzelheiten der Entfesslungseffekte sind in den Tooltips der jeweiligen Waffenverzauberungen erfasst."}
MultiLanguageSpellData['de'][73681] = {name = "Wind entfesseln", additional_info = "100 Meter Reichweite\nSofort\nBenötigt Nahkampfwaffe\n[q]Entfesselt die auf der Waffe des Schamanen liegende Windzornverzauberung, wodurch einem feindlichen Ziel 90% Waffenschaden zugefügt werden. Zudem wird das Nahkampfangriffstempo des Schamanen um 50% erhöht. Hält 6 Waffenschwünge oder 12 Sek. lang an."}
MultiLanguageSpellData['de'][73682] = {name = "Frost entfesseln", additional_info = "100 Meter Reichweite\nSofort\n[q]Entfesselt die auf der Waffe des Schamanen liegende Frostbrandverzauberung, wodurch einem feindlichen Ziel 969 Frostschaden zugefügt werden und sein Bewegungstempo 5 Sek. lang um 50% verringert wird. Der Effekt wird verstärkt, wenn das Ziel bereits von einem bewegungsverringernden Frosteffekt betroffen ist."}
MultiLanguageSpellData['de'][73683] = {name = "Flammen entfesseln", additional_info = "100 Meter Reichweite\nSofort\n[q]Entfesselt die auf der Waffe des Schamanen liegende Flammenzungenverzauberung, wodurch einem gegnerischen Ziel 1241 Feuerschaden zugefügt wird und der verursachte Schaden des nächsten Feuerzaubers des Schamanen um 30% erhöht wird."}
MultiLanguageSpellData['de'][73684] = {name = "Erde entfesseln", additional_info = "100 Meter Reichweite\n{Sofort} {15 sek. Abklingzeit}\n[q]Entfesselt die auf der Waffe des Schamanen liegende Felsbeißerverzauberung, befiehlt dem Ziel, Euch anzugreifen, und erhöht die von Euch gegen das Ziel erzeugte Bedrohung für 5 Sek. um 200%."}
MultiLanguageSpellData['de'][73685] = {name = "Leben entfesseln", additional_info = "100 Meter Reichweite\n{Sofort} {15 sek. Abklingzeit}\n[q]Entfesselt die auf der Waffe des Schamanen liegende Lebensgeisterverzauberung, wodurch ein befreundetes Ziel um 3154 geheilt und der Effekt der nächsten direkten Heilung oder von 'Heilender Regen' des Schamanen um 30% erhöht wird."}
