MultiLanguageSpellData['de'][76433] = {name = "[q3]Schneide des Enthaupters", additional_info = "Wirken in 2 sek. 5\nTools: Schmiedehammer\nReagenzien:\nGefaltetes Obsidium (20), Flüchtige Erde (8)\n[q3]Schneide des Enthaupters\nWird beim Anlegen gebunden\nEinhändig Axt\n1,127 - 2,094 Schaden Tempo 2.60\n(619.42 Schaden pro Sekunde)\n+98 Beweglichkeit\n+147 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 65.\n[q2]Erhöht Eure Meisterschaftswertung um + 65.\nHaltbarkeit 90 / 90\n81"}
MultiLanguageSpellData['de'][76434] = {name = "[q3]Kaltgeschmiedete Klinge", additional_info = "Wirken in 2 sek. 5\nTools: Schmiedehammer\nReagenzien:\nGefaltetes Obsidium (15), Flüchtige Erde (6), Flüchtiges Wasser (4)\n[q3]Kaltgeschmiedete Klinge\nWird beim Anlegen gebunden\nEinhändig Dolch\n780 - 1,449 Schaden Tempo 1.80\n(619.17 Schaden pro Sekunde)\n+98 Beweglichkeit\n+147 Ausdauer\n[q2]Erhöht Eure Trefferwertung um + 65.\n[q2]Erhöht Eure kritische Trefferwertung um + 65.\nHaltbarkeit 65 / 65\n81"}
MultiLanguageSpellData['de'][76435] = {name = "[q3]Feuergeätzter Dolch", additional_info = "Wirken in 2 sek. 5\nTools: Schmiedehammer\nReagenzien:\nElementiumbarren (20), Flüchtige Erde (12), Flüchtiges Feuer (4)\n[q3]Feuergeätzter Dolch\nWird beim Anlegen gebunden\nEinhändig Dolch\n368 - 684 Schaden Tempo 1.70\n(309.41 Schaden pro Sekunde)\n+147 Ausdauer\n+98 Intelligenz\n[q2]Erhöht Eure Trefferwertung um + 65.\n[q2]Erhöht Eure Tempowertung um + 65.\n[q2]Erhöht die Zaubermacht um + 1.307.\nHaltbarkeit 65 / 65\n81"}
MultiLanguageSpellData['de'][76436] = {name = "[q3]Lebenskrafthammer", additional_info = "Wirken in 2 sek. 3\nTools: Schmiedehammer\nReagenzien:\nGefaltetes Obsidium (4), Elementiumbarren (12), Flüchtige Erde (10), Flüchtiges Wasser (6)\n[q3]Lebenskrafthammer\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n455 - 845 Schaden Tempo 2.10\n(309.52 Schaden pro Sekunde)\n+147 Ausdauer\n+98 Intelligenz\n+65 Willenskraft\n[q2]Erhöht die Zaubermacht um + 1.307.\n[q2]Erhöht Eure Meisterschaftswertung um + 65.\nHaltbarkeit 90 / 90\n81"}
