MultiLanguageSpellData['de'][78144] = {name = "Sturmschlag", additional_info = "{8% von Grundmana} {Nahkampfreichweite}\n{Sofort} {8 sek. Abklingzeit}\nBenötigt Nahkampfwaffe\n[q]Greift das Ziel sofort mit beiden Waffen an. Zusätzlich werden die nächsten 4 Quellen des Naturschadens, der dem Ziel zugefügt wird, um 20% erhöht. Hält 12 Sek. lang an."}
MultiLanguageSpellData['de'][78145] = {name = "Erdschock", additional_info = "{18% von Grundmana} {25 Meter Reichweite}\n{Sofort} {6 sek. Abklingzeit}\n[q]Schockt das Ziel unmittelbar mit erschütternder Kraft und verursacht 2142 bis 2258 Naturschaden. Unterbricht außerdem das Wirken von Zaubern und verhindert 2 Sek. lang, dass diese Art Zauber gewirkt werden kann."}
MultiLanguageSpellData['de'][78146] = {name = "Lavapeitsche", additional_info = "{4% von Grundmana} {Nahkampfreichweite}\n{Sofort} {6 sek. Abklingzeit}\nBenötigt Nahkampfwaffe\n[q]Lädt Eure Schildhandwaffe mit Lava auf, verursacht sofort 100% Waffenschaden der Schildhandwaffe. Der Schaden ist um 25% erhöht, wenn Eure Schildhandwaffe mit 'Flammenzunge' verzaubert ist."}
