MultiLanguageSpellData['de'][79563] = {name = "Eisrüstung", additional_info = "630 Mana\nSofort\n[q]Erhöht die Rüstung um 2000 und den Frostwiderstand um 50. Wenn ein Feind den Zaubernden schlägt, kann 5 Sek. lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen seinen Angriffen um 0% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an."}
