MultiLanguageSpellData['de'][79862] = {name = "Meucheln", additional_info = "{60 Energie} {Nahkampfreichweite}\nSofort\n[q]Fügt einem Gegner 150% Schaden zu, aber nur, wenn von hinten angegriffen wird."}
MultiLanguageSpellData['de'][79863] = {name = "Blutsturz", additional_info = "{40 Energie} {Nahkampfreichweite}\nSofort\n[q]Verursacht Waffenschaden und erhöht den erlittenen körperlichen Schaden eines Gegners 10 Sek. lang um 20%."}
MultiLanguageSpellData['de'][79864] = {name = "Schattenschritt", additional_info = "{20 Energie} {40 Meter Reichweite}\n{Sofort} {30 sek. Abklingzeit}\n[q]Versucht, in die Schatten zu tauchen, um hinter dem Gegner zu erscheinen."}
MultiLanguageSpellData['de'][79865] = {name = "Frostrüstung", additional_info = "{Sofort} {10 sek. Abklingzeit}\n[q]Umgibt den Zaubernden mit einer Frostschicht, die 30 Min. lang bestehen bleibt. Das dicke Eis erhöht die Rüstung, verlangsamt das Bewegungstempo von Nahkampfangreifern und erhöht die Zeit zwischen ihren Angriffen."}
MultiLanguageSpellData['de'][79866] = {name = "Tödlicher Wurf", additional_info = "{20 Energie} {30 Meter Reichweite}\nSofort\n[q]Wirft einen Dolch auf ein gegnerisches Ziel und verursacht 24 bis 29% Waffenschaden. Unterbricht außerdem das Wirken von Zaubern und verhindert 3 Sek. lang, dass diese Art Zauber gewirkt werden kann."}
MultiLanguageSpellData['de'][79867] = {name = "Phase 20 to Normal", additional_info = nil}
MultiLanguageSpellData['de'][79868] = {name = "Arkanschlag", additional_info = "{7% von Grundmana} {30 Meter Reichweite}\nWirken in 2.5 sek.\n[q]Überzieht einen Feind mit Energie und verursacht Arkanschaden. Mit jedem Wirken von 'Arkanschlag' werden der verursachte Schaden aller Arkanzauber um 50% und die Manakosten von 'Arkanschlag' um 150% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar und hält 10 Sek. lang an oder bis ein Arkanzauber außer 'Arkanschlag' gewirkt wurde."}
MultiLanguageSpellData['de'][79869] = {name = "Arkane Geschosse", additional_info = "{35 Mana} {30 Meter Reichweite}\nKanalisiert (Wirken in 5 sek.)\n[q]Schleudert magische Geschosse auf einen Feind und verursacht 5 Sek. lang pro Sekunde Arkanschaden."}
MultiLanguageSpellData['de'][79870] = {name = "Wilde Attacke", additional_info = "{5 Wut} {8 - 25 Meter Reichweite}\n{Spontanzauber} {15 sek. Abklingzeit}\n[q]Stürmt auf einen Gegner zu, macht ihn bewegungsunfähig und unterbricht gewirkte Zauber. Hält bis Abbruch lang an."}
MultiLanguageSpellData['de'][79871] = {name = "Tollkühnheit", additional_info = "Sofort\n[q]Immun gegen Furchteffekte.\n Alle Angriffe treffen kritisch.\n Rüstung um 35% verringert."}
MultiLanguageSpellData['de'][79872] = {name = "Schockwelle", additional_info = "{Wirken in} {2 sek. 20 sek. Abklingzeit}\n[q]Schickt dem Krieger eine Energiewelle voraus, verursacht Schaden und betäubt 4 Sek. lang alle Einheiten innerhalb eines kegelförmigen Bereichs von 10 Metern."}
MultiLanguageSpellData['de'][79875] = {name = "Ongolongoschmettern!", additional_info = "10 Meter Reichweite\nWirken in 0.5 sek.\n[q]Stößt das Ziel zurück."}
MultiLanguageSpellData['de'][79876] = {name = "Blutdurst", additional_info = "Nahkampfreichweite\nSofort\n[q]Heilt den Zaubernden um 1% seiner maximalen Gesundheit."}
MultiLanguageSpellData['de'][79877] = {name = "Blutdurst", additional_info = "Nahkampfreichweite\nSofort\n[q]Greift das Ziel sofort an und verursacht 120% normalen Waffenschaden. Zudem stellen erfolgreiche Nahkampfangriffe 1% der maximalen Gesundheit wieder her. Der Effekt hält 10 Sek. lang an."}
