MultiLanguageSpellData['de'][79879] = {name = "Elektrische Entladung", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Fügt bis zu 3 Gegnern im Umkreis von 8 Metern 43875 bis 46125 Naturschaden zu."}
