MultiLanguageSpellData['de'][79881] = {name = "Zerschmettern", additional_info = "Nahkampfreichweite\nWirken in 1.5 sek.\n[q]Zerschmettert den Gegner und verursacht Waffenschaden plus zusätzlichen Schaden."}
