MultiLanguageSpellData['de'][79884] = {name = "Blitzschlag", additional_info = "{15 Mana} {40 Meter Reichweite}\nWirken in 3 sek.\n[q]Deckt einen Feind mit Blitzschlägen ein und fügt ihm Naturschaden zu."}
