MultiLanguageSpellData['de'][79891] = {name = "Horn des Winters", additional_info = "-10 Runenmacht\nSpontanzauber\n[q]Der Todesritter bläst das Horn des Winters und erhält 10 Runenmacht. Stärke und Beweglichkeit werden um 5 erhöht. Hält 2 Min. lang an."}
MultiLanguageSpellData['de'][79892] = {name = "Wasserschild", additional_info = "Sofort\n[q]Der Zaubernde wird von 3 Wasserkugeln umgeben. Gegen den Zaubernden gerichtete Angriffe oder Zauber verursachen Frostschaden und verlangsamen das Zaubertempo des Angreifers. 3 Aufladungen. Hält 10 Min. lang an.\n(4s Abklingzeit)"}
