MultiLanguageSpellData['de'][79895] = {name = "Froststoß", additional_info = "{-10 Runenmacht} {Nahkampfreichweite}\nSpontanzauber\nBenötigt Nahkampfwaffe\n[q]Schlägt das Ziel sofort und verursacht 110% Waffenschaden als Frostschaden."}
