MultiLanguageSpellData['de'][79954] = {name = "Teufelsrüstung", additional_info = "28% von Grundmana\nSofort\n[q]Umgibt Euch mit Teufelsenergie, welche Eure Zaubermacht um 10% erhöht. Zusätzlich regeneriert Ihr alle 5 Sek. 2% Eurer gesamten Gesundheit. Es kann immer nur eine Art Rüstungszauber gleichzeitig aktiv sein. Hält 30 Min. lang an."}
MultiLanguageSpellData['de'][79955] = {name = "Feuerregen", additional_info = "{35 Mana} {30 Meter Reichweite}\nKanalisiert (Wirken in 9 sek.)\n[q]Lässt einen Schmelzregen niedergehen, der alle Feinde im ausgewählten Gebiet verbrennt und ihnen 9 Sek. lang alle 3 Sek. Feuerschaden zufügt."}
MultiLanguageSpellData['de'][79956] = {name = "Fluch der Elemente", additional_info = "{10% von Grundmana} {30 Meter Reichweite}\nSofort\n[q]Verflucht das Ziel 30 Sek. lang und verringert so seinen Widerstand gegen Arkan-, Feuer-, Frost-, Natur- und Schattenschaden um 45, während der erlittene Magieschaden um 8% erhöht wird. Es kann immer nur jeweils ein Fluch pro Zauberndem auf einem beliebigen Ziel aktiv sein."}
MultiLanguageSpellData['de'][79957] = {name = "Seelenverbindung", additional_info = "{16% von Grundmana} {100 Meter Reichweite}\nSofort\n[q]Bei Aktivierung werden 1% des von Euch erlittenen Schadens auf Euren Wichtel, Leerwandler, Sukkubus, Teufelsjäger, Teufelswache oder versklavten Dämon umgelenkt. Dieser Schaden kann nicht vermieden werden. Hält an, solange der Dämon aktiv ist und kontrolliert wird."}
