MultiLanguageSpellData['de'][79965] = {name = "Schild des Rächers", additional_info = "{30 Mana} {30 Meter Reichweite}\nWirken in 1 sek.\n[q]Schleudert einen heiligen Schild auf den Gegner, der Heiligschaden zufügt, ihn benommen macht und dann auf weitere nahe Gegner überspringt. Wirkt auf insgesamt 2 Ziele."}
MultiLanguageSpellData['de'][79966] = {name = "Weihe", additional_info = "22% von Grundmana\nSofort\n[q]Weiht das Land unter dem Zaubernden und fügt Gegnern, die das Gebiet betreten, im Verlauf von 8 Sek. Heiligschaden zu."}
MultiLanguageSpellData['de'][79967] = {name = "Heiliger Schild", additional_info = "10% von Grundmana\nSofort\n[q]Erhöht die Blockchance 10 Sek. lang um 30% und verursacht, während der Effekt aktiv ist, mit jedem Blocken Heiligschaden. Jedes Blocken zehrt eine Aufladung auf. 3 Aufladungen."}
MultiLanguageSpellData['de'][79968] = {name = "Segen der Könige", additional_info = "30 Meter Reichweite\nSofort\n[q]Belegt ein befreundetes Ziel mit einem Segen, welcher 5 Min. lang seine Stärke, Beweglichkeit, Ausdauer und Intelligenz um 5% erhöht."}
MultiLanguageSpellData['de'][79970] = {name = "Göttlicher Sturm", additional_info = "{20% von Grundmana} {Nahkampfreichweite}\nSofort\n[q]Ein sofortiger Waffenangriff, der bei bis zu 4 Feinden innerhalb von 8 Metern Heiligschaden verursacht."}
MultiLanguageSpellData['de'][79971] = {name = "Hammer des Zorns", additional_info = "{30 Mana} {40 Meter Reichweite}\nWirken in 2 sek.\n[q]Schleudert einen Hammer, der einem Gegner Heiligschaden zufügt."}
MultiLanguageSpellData['de'][79972] = {name = "Siegel der Wahrheit", additional_info = "14% von Grundmana\nSofort\n[q]Erfüllt den Paladin mit heiliger Macht, durch den Angriffe auf Einzelziele den Effekt 'Tadel' auslösen, der im Verlauf von 15 Sek. [(0.01 * Zaubermacht + 0.0193 * Angriffskraft) * 5 */ 100] zusätzlichen Heiligschaden verursacht. 'Tadel' ist bis zu 5-mal stapelbar. Sobald 5 Stapel erreicht werden, verursacht jeder Angriff des Paladins zusätzlich 12% Waffenschaden als Heiligschaden. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein. Hält 5 Min. lang an.\n\n Die Entfesselung der Energie dieses Siegels fügt einem Feind (1 + 0.223 * Zaubermacht + 0.142 * Angriffskraft) Heiligschaden zu, dieser Schaden wird für jeden Stapel von 'Tadel' auf dem Ziel um 10% erhöht."}
MultiLanguageSpellData['de'][79973] = {name = "Wirbelwind", additional_info = "Kanalisiert (Wirken in 5 sek.)\n[q]Fügt Gegnern vor dem Zaubernden alle 1 Sek. 32987 bis 37012 Schaden zu."}
MultiLanguageSpellData['de'][79974] = {name = "Wirbelwind", additional_info = "Sofort\n[q]Fügt Gegnern vor dem Zaubernden alle 1 Sek. 32987 bis 37012 Schaden zu."}
