MultiLanguageSpellData['de'][80012] = {name = "Schimärenschuss", additional_info = "45% von Grundfokus 35 Meter Reichweite\n10 sek. Abklingzeit\nBenötigt Distanzwaffe\n[q]Verursacht 125% Waffenschaden, frischt die Dauer Eures auf das Ziel wirkenden Gifts auf und löst einen Effekt aus:\n\n Schlangengift - Verursacht sofort 40% des von Eurer Fähigkeit 'Schlangengift' verursachten Schadens.\n\n Viperngift - Stellt für Euch sofort Mana in Höhe von 60% des von Eurer Fähigkeit 'Viperngift' entzogenen Manas her.\n\n Skorpidgift - Versucht, das Ziel 10 Sek. lang zu entwaffnen. Dieser Effekt kann nicht öfter als ein Mal pro Minute auftreten."}
MultiLanguageSpellData['de'][80013] = {name = "Schimärenschuss - Schlange", additional_info = "100 Meter Reichweite\n[q]Verursacht 265% Waffenschaden, frischt die Dauer Eures auf das Ziel wirkenden Gifts auf und löst einen Effekt aus:\n\n Schlangengift - Verursacht sofort 40% des von Eurer Fähigkeit 'Schlangengift' verursachten Schadens.\n\n Viperngift - Stellt für Euch sofort Mana in Höhe von 60% des von Eurer Fähigkeit 'Viperngift' entzogenen Manas her.\n\n Skorpidgift - Versucht, das Ziel 10 Sek. lang zu entwaffnen. Dieser Effekt kann nicht öfter als ein Mal pro Minute auftreten."}
